/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080307-3","meetingId":"h20-c-budget","date":"2008年3月7日","dateIso":"2008-03-07","committee":"予算特別委員会","time":"午前１０時０２分～午後６時２２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"認定こども園の解釈を私なりにしているんですが、保護者が働いている、いないにかかわらず、教育ならびに保育の就学前教育を行うという機能と私は解釈をしておりますけれども、そんな中、２１３ページの私立認定こども園運営費助成、ならびに、２１５ページに認定こども園事業とありますけれども、これはなぜこの２つの項目を別々にしているのかということと、それから。","respondent":"小林保育課長","answer":"一方、ページお戻りいただきまして、２１３ページの認定こども園ですが、これは私立認定こども園運営助成費ということで、こちら、本年、平成２０年１２月１日に開園を予定しております学習研究社内に設置しました私立の認可保育園をベースにいたしました認定こども園の措置費。","voiceIndex":4,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"最初のほうの認定こども園というのは、これはあくまでも公立、いわゆる区立の認可保育園に設定をした、設定をしたというかな、認定こども園という感覚で、これは私が調べたところによると、保育型という認定こども園なのかなと思うんですけれども、これは例えば、戻って、私立の認定こども園の運営助成については、例えば国からとか、補助金とか、助成金というんでしょうか。","respondent":"小林保育課長","answer":"今回、認可保育園の中でも、認定こども園ということで、事業者の裁量が増える他方で、事業者の負担も増してくるところがありますので、品川区といたしましては、開設に向けて、既存の認可保育園を参照しながら。","voiceIndex":6,"id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"そうしたら、先ほどもちょっと話をしましたけど、認定こども園には、多分４種類あると思うんですね。幼保連携型、それから、幼稚園型、保育園型。ほかの幼保連携型とか、幼稚園型とか、地方裁量型についての品川区の考え方というのはどうなんでしょうか。","respondent":"高橋幼保一元担当課長","answer":"この制度は、平成１８年の１０月に国が定めまして、東京都が平成１８年の１２月にこの認定こども園にかかわる条例をつくったというところで、品川区全域の部分で調査をしましたけれども、今のところ、私立幼稚園、保育園に関しては、考えているというところはありますけれども。","voiceIndex":8,"id":"exchange-003"},{"speaker":"金野委員","kind":"提案","question":"私のほうからは、２１１ページの認証保育所利用助成についてと、２点目が、２１７ページにあります保育園運営費の中の子育てプラン作成支援、もし時間がありましたら、２１９ページの助産師によるベビーマッサージ等事業についてお伺いします。そこで、この制度の創設に当たりまして、何点か確認をしますが、助成額の割合について、所得階層と、その階層に応じた助成額をまずお聞きしたいと思います。","respondent":"小林保育課長","answer":"現階層は、認可保育園の場合、Ｄの１階層から２１階層まですが、この階層に基づきまして仮算定をいたしましたときに、Ｄの１２階層から１８階層までが１万円、それから、Ｄの４階層からＤの１１階層までが２万円、Ｃの３階層からＤの３階層までが３万円、そして。","voiceIndex":11,"id":"exchange-004"},{"speaker":"金野委員","kind":"質問","question":"階層は、多分公立保育園の階層に基づいてということで今ご説明をしていただいたところだと思うんですが、この制度の利用手続というんでしょうか、方法と手順を教えてください。","respondent":"小林保育課長","answer":"４月になりましたら、早い時期に各認証保育所の事業者に説明会を持ちまして手順の了解を得て、方法を確定してまいりたいと考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問","question":"そうすると、認証保育所に入園をした。その軽減のためにこの制度をというふうにしたことを考えますと、年に２回申請をして、いただくというと、やはり毎月の負担の軽減のためと考えると、年に２回という考え方はどんなものでしょうかというふうに思ってしまうんです。何回かに分けて、例えば２カ月に一遍、３カ月に一遍とか、最高は毎月なんですけれども、どうなんでしょうか。お願いします。","respondent":"小林保育課長","answer":"幼稚園の就園奨励費等のシステムも参考にいたしまして、事務的に成り立つ時期というふうに考えて設定いたしましたが、それが果たして２回がいいのか、３回がいいのかというのは、ご指摘をもとにして、今後精査して、もう一度検討してまいりたいとは思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"金野委員","kind":"質問・要望","question":"続きまして、保育園運営費についての中の子育てプラン作成支援についてお伺いしたいと思います。新事業の中で、入園の予約ができる制度、いわゆる育児休業の切れ目のない保育サービスとして創設していただきました入園予約と、それから、多様な働き方への対応として考えていただいた短時間就労に対する保育サービスとしての保育制度というんでしょうか、その概要をお願いします。","respondent":"小林保育課長","answer":"しかし、そういった入りづらい方についても、保育園へのニーズがありますので、これについては一定、区分けして、短時間の就労の方に対応する枠を特別に持つという形で創設するものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"細かに、丁寧な説明ありがとうございました。短時間就労に関しても、パートタイム、アルバイトでつないでいるお母さんたちが、非常にポイントが低いのでというふうにお困りの点を酌んでいただいて、いわゆる申請の見直しというんでしょうか、制度の見直しをしていただいて、このことも本当にありがたいと思います。ありがたいところでありますので、現状はどんなものなんでしょうか。","respondent":"小林保育課長","answer":"今後も対応に努力をしてまいります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"２１３ページ、保育園運営費について質問いたします。少子化が叫ばれる中、子育て支援の拡充が求められています。これから結婚や子育てをしようという若者の間では、２人に１人が非正規雇用。今年の４月入園の一時募集で、認可保育園に応募したものの、どこにも入れなかった子どもの人数を教えてください。地域的にはどうだったのでしょうか。子どもの年齢や地域的なところでの傾向もあわせて教えてください。","respondent":"小林保育課長","answer":"この点につきましては、今後も認証保育所、あるいは時期が少しずれておりますけれども、先ほどご質問に出ました学習研究社等の施設開設も含めて、五反田の地域需要は想定しておりましたので、引き続き対応、改善に努力してまいります。","voiceIndex":22,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと数を教えていただけなかったので、これは改めて応募者数を教えていただきたいのと、あと、かなり具体的に聞いたんですけれども、４月入園の１次募集で、区の認可保育園に応募したものの、１次募集であぶれてしまった子どもの人数を教えてくださいとお伺いしたので、そちらをあわせてお伺いしたいと思います。夫は月５０時間の残業。先ほどの数字とあわせてお伺いします。","respondent":"小林保育課長","answer":"それをねらったのが今回の新たな予約制度ということですので、この予約制度が早くできていれば、もうちょっと希望に沿えたところはあるかもしれませんけれども、そういったケースも含めて、限られた中で対応していく予定をしています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"努力はしているということですけれども、理想は理想としてという話もありましたが、理想にとどまらず、理想の追求に向けて頑張ってほしいと思います。これまでは積極的に再開発を推進して、納税者、特に中堅所得者層やファミリー層を呼び込んでおきながら、保育の需要増に伴う計画や見通しが甘かったということにならないんでしょうか。きちんとこれは計画を持つべきだと思います。","respondent":"小林保育課長","answer":"年齢的な傾向を含めたところですけれども、現状の中で全体の区の人口に比べて、このエリアの人口の増が多いということは承知しておりまして、それに応じて、先ほどご紹介いたしました学習研究社の認証保育所のほか、品川保育園の移転に伴う定数の増等。","voiceIndex":26,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"今、大崎地区の話がありまして、認証保育所ということも言葉があったので、そのことを１点だけ、何なのかということをお伺いしたいのと、これはぜひ認可保育園でやるべきじゃないかと思ったので、もし大崎でやるのであれば、認可保育園でやるべきだと思いますが、どうなのかということと、あと、大きな問題といたしましては、やはり待機児ゼロを目指すべきだと思います。","respondent":"古川児童保健事業部長","answer":"現実的な対応をやっていかないと、認可保育園だけを今後の施策の中心に置くことは非常に難しいだろう、こう思ってあります。","voiceIndex":28,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問","question":"初めに、本日、２１３ページにあります私立認定こども園運営費助成についてと、２１７ページ、オアシスルームについてお伺いします。オアシスルームについてなんですが、平成１９年度の予算で９園に対して、約９,２００万円の予算がついて、平成２０年度、７園で４,２００万円、２園減って予算が半分になっているということ。よろしくお願いします。","respondent":"小林保育課長","answer":"そしてまた、中原保育園は、来期ぷりすくーる西五反田への移行を予定しておりますので、これもこちらのところから減額になり、そして、新たにぷりすくーる西五反田の委託経費の中に費用が算入されている等の財源上の構成を行っておるところです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"提案","question":"それだけ区民のニーズにこたえているんだなと思います。１つ２つあったら、お答えいただければと思います。それと、オアシスルームなんですが、これは要望になるのですが、品川区役所内に一時保育等、生活支援型一時保育の施設を設置できないかという提案をしたいのですが、ご見解を聞かせていただきたいと思います。よろしくお願いします。","respondent":"小林保育課長","answer":"オアシスルームにつきましては、開設から需要に対応するため園数を増やすと同時に、必要に応じて展開する地域エリアの調整等を行いまして、現在の需要対応をしています。","voiceIndex":33,"id":"exchange-014"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"課長の答弁、区役所内に保育園がない。オアシスルームというのはもともと保育園の中にあるという中で、ぜひ私の要望を新たに、保育園の事業所の設置を区役所内に。そうすると、賛否両論あると思うのですが、私はぜひ、そういった観点からも、区役所内に保育園、特に一時保育、そして、病後児保育、病児保育等を含めたご検討をしていただきたいのですが、ご答弁をよろしくお願いいたします。","respondent":"小林保育課長","answer":"職員のというところまで踏み込んでいただいたのは大変ありがたいと思います。しかしながら、まずもって区民のということで対応してまいるところですので、アイデアについては、思いの中におさめて、将来の課題とさせていただきたいと思います。","voiceIndex":35,"id":"exchange-015"},{"speaker":"石田（慎）委員","kind":"提案","question":"昨日、私、結婚サポート事業の質問をした際にも、やはり区が事業に取り組む。そんな中、区役所内にあるというのは、一番の安心感があるのかなと。そういった思いで提案をさせていただきました。オアシスルームの、こんなときに利用できますの中に、その他区長が認めたときというのがあるのですが、もし何か具体的なものがありましたら、１つ２つ教えていただければなと思います。よろしくお願いします。","respondent":"小林保育課長","answer":"通常の一時保育であれば、それぞれの要件等がありますので、公平性の関係からお引き受けできない。だけど、今日この人、どうするんだろう、明日どうするんだろうといったときには、区長の温かい心をもって、これは個々のケースに応じてお預かりする判断をしている。","voiceIndex":37,"id":"exchange-016"},{"speaker":"石田（慎）委員","kind":"意見","question":"ぜひ区長の温かい心を反映させていただければなと思います。そういった意味もあるのかなと、そのように思います。ぜひ今後とも保育の充実、さらに拡大をしていったら、どんどん、どんどん品川区がよくなると、どこの区からも、皆さん、品川区に来てしまって、また足りなくなってしまうのかもしれないですが、区民にとって充実した保育をぜひ進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"確認","question":"私は１８７ページの民生委員経費について伺います。民生委員は、平成２０年度予算でも、悪質商法対策ネットワークでも重要な担い手と表現されています。民生委員の委嘱元など、立場の確認。そして、ボランティアである確認。それと守秘義務について伺いたいと思います。それと、職務内容は結構多岐にわたると思いますので、対象となる主な方々、この点を伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"位置づけですけれども、特別職の地方公務員という位置づけになっておりますので、守秘義務が課せられていると解釈されております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"職務内容と、あと対象となる主な方々、地域でどのような方を対象とされているのか、改めて伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"対象の方は、高齢者、地域のそういう支援を必要とする高齢者の方ですとか、生活保護を受けている方、あるいは、子育てのご家庭の方等々です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その応対や相談も、身近という中で、随時、ご近所ですから、２４時間体制の場合もある。その中で、要望とあわせて伺いたいと思います。民生委員を知っているのか。あるいは、今後もそういう実態調査をもとに民生委員の活動に役立てたり、あるいは、今申し上げた広報活動の充実が、行政、あるいは私たちも含めたまちの人たちが応援する中で重要と思いますが、この２点、お伺いしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"そういった心理的負担を解消する１つの方策として、研修等、どうなのかですけれども、これにつきましては、新任の際に、一定の新任の方への研修をまず行います。","voiceIndex":45,"id":"exchange-020"},{"speaker":"渡辺委員","kind":"確認","question":"最後、確認ですが、その実態調査の中で、民生委員自体の調査もありますが、地域の人たちがどのように民生委員を思われているか。そういった、困ったときの頼りどころ、どこに行けばいいというのを知っていられるかどうか。この点を現場の方々は心配をされていたので、これから具体的な実態調査の項目になり得るかどうかだけお伺いしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"調査につきましては、また機会をとらえて実施をしていきたいと考えております。日ごろから、地域の皆様に対しては、例えば在宅介護支援センターなどを通じまして、いろいろな相談等に応じたときに、民生委員の存在、あるいは活動、役割等についてもお知らせをしています。","voiceIndex":47,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"私は３点お願いします。１９５ページの住宅用火災警報器設置促進事業、それから、１９９ページの知的障害者また精神障害者のサポート事業、それから、戻りまして、１８９ページの原小学校跡の西大井シルバーセンター施設整備助成。住宅用火災警報器についてなんですが、昨年の７月から始まったかと思うんですが、今年度のこれまでの助成実績件数と昨年度予算を立てたときの見込み件数を教えてください。","respondent":"蓼沼高齢福祉課長","answer":"火災警報器の実績ですけれども、２月末現在で１１２世帯に取りつけを行ってあります。平成１９年度の件数の想定ですけれども、１,２００世帯です。","voiceIndex":50,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"たしか１,２００世帯を３年間やるというふうにちょっと記憶しているんですけれども、その中で、７月から始まって、確かに１年間はないので、ある程度しようがないのかなと思うんですけれども、１１２世帯ということで、なかなか実績が上がってないなという感想なんですけど、その中で、昨日もちょっと出ましたけれども、平成２２年から義務化されるという中で、私どももさまざま取り上げて。","respondent":"蓼沼高齢福祉課長","answer":"実績が少なかった理由ですけれども、対象者の要件を、年齢と、例えば単身であれば６５歳以上の単身者であること、あるいは、高齢者のみの世帯という、年齢、世帯の要件と、それから、所得におきましては。","voiceIndex":52,"id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"今、対象者がひとり暮らしだと６５歳以上とおっしゃいましたが、これは、今までは７０歳以上だったんですよね。来年度から、恐らくこうした実績を見込んで、対象者を拡大するということで、ひとり暮らしについては６５歳になるんですかね、７０歳から。ちょっと下がっているという。","respondent":"蓼沼高齢福祉課長","answer":"そういった一定の要件、所得、保険料段階と、それから年齢要件等によっていることが１つと、それから、ご指摘ありましたように、実施が平成２２年４月から義務づけということで。","voiceIndex":54,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問・要望","question":"１点お聞きしたいのは、義務化されるんですけれども、これは罰則があるんですか。例えば平成２２年度でだめだと。確認したいのと、それであれば、この間、自転車等のいろんな話もありますが、罰則がなくて努力義務だと、そういったこともひとつ影響してくるのかなというのであれば、なおさらＰＲをしていかないといけないなと。","respondent":"蓼沼高齢福祉課長","answer":"ただ、ひとり暮らし高齢者等の方が、火災による死亡が増えてきているという、そういう背景がありまして、警報器の設置に今取り組んでいるところですので、今後ともいろいろさまざまな機会を活用してＰＲのほうに努めてまいりたいと考えています。","voiceIndex":56,"id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"よろしくお願いします。それから、来年度、新しい事業で知的・精神障害者の生活サポート２４というのが始まりますが、これを実施される背景と、あと、これは例えば都とか国の補助金、支出金が入っているのかどうか、教えてください。","respondent":"高橋障害者福祉課長","answer":"この事業の背景ですが、障害者自立支援法が施行されたということで、地域で暮らし続けるということをサポートするということになりました。そのところによりまして、知的障害者、精神障害者ということで、サポートしていくものです。","voiceIndex":58,"id":"exchange-026"},{"speaker":"武内委員","kind":"質問","question":"対象者は、今、グループホームとひとり暮らしの精神障害者、知的障害者の方。そうすると、例えば家族と住んでいる方で、これから先々のことを考えて自立して１人で暮らしてもらおうとか、そういった方については、とりあえずこの中では対象になってないということでしょうか。","respondent":"高橋障害者福祉課長","answer":"ひとり暮らしで地域で何かあったときに、困っているときにサポートしていくということで、例えば日常生活のところで、これ買ってもいいかなとかということで、知的障害者の方について聞いたり、どこに行くにはどうしたらいいのかなということで。","voiceIndex":60,"id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"非常にいい取り組みだと思うんですね。そのまま１カ月分の給料を一気に使ってしまうとか、そういったことのお金の管理なんかも例えば含まれてくるのかということと、あと、２４時間体制で、夜間でも、緊急時でも、場合によっては駆けつけるよというような、プレス発表の（４）番で書いてあるんですけれども、これは大丈夫かなという。その辺の体制についても教えてください。","respondent":"高橋障害者福祉課長","answer":"それぞれ知的障害者、精神障害者がどういうサポートをすればいいのかというのは、それぞれの本人の状況が違いますので、その辺について詳しく面談した上で登録し、その後、電話番号、または２４時間の携帯電話を教えるというような状況です。","voiceIndex":62,"id":"exchange-028"},{"speaker":"武内委員","kind":"質問","question":"そうすると、例えば精神障害の方なんか、いろんな方がいて、重い方から軽い方がいると思うんですけれども、例えば聞こえないものが聞こえたりとか、見えないものが見えたりとか、そういう方なんかも、どこまで対象にするのか。そうすると、夜中なんかも、しょっちゅう電話がかかってきたりとか、そういうこともあり得ると思うんですけれども、その辺のところは、まだこれからなのか。そこを教えてください。","respondent":"高橋障害者福祉課長","answer":"医療が必要だという精神障害者については、相談を受けた上で、医療のほうにご紹介するという形になっております。その辺では、一応面談した上で登録可能かどうか、それと、ご本人がどういう状況かというのは、この辺には医療関係者との連携も必要かと思って、進めします。","voiceIndex":64,"id":"exchange-029"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は、２１９ページの児童センター館事業、このことについてと、午前中かなり多くの委員から質問があったと思うんですけれども、２１７ページの子育て支援事業、こちらのほうについてお伺いしたいと思います。２１９ページの児童センター館事業、この中で新規の事業で親育ち支援事業というのがあります。","respondent":"諸岡児童課長","answer":"その間は、お母さんについては、別室でヨガをやっていただいたり、フラワーアレンジメントをやっていただいたりということで、ちょっとリフレッシュをしていただいて、最後には一家そろってまたいろんなお楽しみをしていただくというようなことで、リフレッシュを含めて。","voiceIndex":68,"id":"exchange-030"},{"speaker":"井桁委員","kind":"質問","question":"必ず家族の支えというものがあって初めて子育てがより充実したものになると思うんですけれども、それに関して、父親講座の中で、例えば入浴、病院でもやっているとは思うんですけれども、子育てについての子どもに対する、そして、赤ちゃんに対する知識だったりとか、そういった講座というのはお考えでしょうか。","respondent":"諸岡児童課長","answer":"もちろん父親講座の中でも考えてまいりますけれども、父親専用の講座で、パパと遊ぼう講座でありますとか、父親のみを対象とした事業を多く持ってあります。その中で、育児知識も含めたアドバイス、そういった内容も盛り込んでおります。","voiceIndex":70,"id":"exchange-031"},{"speaker":"井桁委員","kind":"質問","question":"ぜひとも母親のみならず、本当に家族で子どもを育てていく。そして、地域で子どもを育てていくと、そういった事業をどんどんと展開していっていただけたらと思います。中高生の親育ち支援事業の中で、中高生の子育て体験というのがありまして、そちらについてもお教え願えますでしょうか。","respondent":"諸岡児童課長","answer":"ということで、中高生が乳幼児の１年間の成長、それを目の当たりにしていただくということを通じて、またあるいは、お母さんとお子さんの愛情関係、そういった触れ合いを見ていただくということで、継続して実施していくというところに特徴を持っております。","voiceIndex":72,"id":"exchange-032"},{"speaker":"井桁委員","kind":"質問","question":"継続的といった言葉が先ほどございましたけれども、その中で危惧されるのは、今、兄弟のいない子どもたちといいますか、そういうのが非常に増えている中で、赤ちゃんに対して触れ合ったりとか、そういったときに、事故とか、そういった懸念がされると思うんですけれども、そちらのほうはいかがでしょうか。","respondent":"諸岡児童課長","answer":"もちろん事前に、中高生のほうには、子どもに触れ合っていただく前に、講習という形で、例えば赤ちゃん人形で慣れていただくとか、そういった講習を行った後交流に入るというようなことを予定しております。","voiceIndex":74,"id":"exchange-033"},{"speaker":"井桁委員","kind":"質問・要望","question":"より広い子育て体験ということで実施していただけたらと考えています。そして、この中で、昨年度ございました、食を通じての子育て支援というのが平成１９年度はございましたけれども、今年度は、ここの中では組み込まれておりませんが、今年もそういった講座の開催というのはお考えでしょうか。","respondent":"諸岡児童課長","answer":"今年度につきましては、事業の実施ということで、そういった備品類の整備はございませんが、今年度、５館において活発に食育事業を展開しております。","voiceIndex":76,"id":"exchange-034"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひとも子育てと食というのは、大変結びつきの強いものですので、ぜひともこの事業をさらに活発化していただきたいと思います。その中でなんですけれども、昨年からでもいいんですが、赤ちゃんの訪問事業というのは、実際に何件ぐらいのお宅を訪問して、そういった事業を展開されているのでしょうか。","respondent":"諸岡児童課長","answer":"これは児童課の児童センターと、もともと新生児訪問をやっておりました保健所・保健センターと連携をして事業を実施しているものです。１月末の時点で、双方合わせて約１,７００件の訪問件数を行っております。","voiceIndex":78,"id":"exchange-035"},{"speaker":"井桁委員","kind":"確認","question":"この数字なんですけれども、保健所の方と連携をしてということなんですけれども、全家庭の訪問ということではないですよね。ちょっとその辺の確認をお願いいたします。","respondent":"諸岡児童課長","answer":"目標は、やはり全戸訪問ということを目標にしておりまして、すべての新生児の家庭を目標としております。","voiceIndex":80,"id":"exchange-036"},{"speaker":"井桁委員","kind":"質問","question":"今年から、育児のオーダーメードのプラン作成支援というのがあるんですけれども、そういったのも含めていくと、かなりな時間と経費等かかってくると思うんですけれども、その辺はいかがお考えでしょうか。","respondent":"小林保育課長","answer":"子育てのプラン、こちらも妊娠期の早い時期から想定しておりますので、児童課と連携いたしまして、バックアップできるように努めてまいります。","voiceIndex":82,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１８７ページ、原小学校跡ケアホーム施設整備助成について伺いたいと思います。先日、２月２９日だったでしょうか、大井第三地域センターで建設の説明会が行われました。","respondent":"蓼沼高齢福祉課長","answer":"原小学校跡のケアホームの利用料ですけれども、これは、法人が第一義的には決定するものですけれども、区が当然関与して適切な利用料の設定をしようとすべく、今、検討を進めているところですけれども、説明会でご説明申し上げましたように。","voiceIndex":86,"id":"exchange-038"},{"speaker":"中塚委員","kind":"意見","question":"この施設の利用料を初めて議会に報告されたのが、昨年２月の厚生委員会だと思うんですけれども、当時、課長から１６万円から２０万円だと。よく精査して、なるべく低廉な料金にしたい旨の答弁がありましたけれども、今聞いても、料金はなかなか下がっていない。なぜ下がらないのか。その理由をご説明いただけますか。","respondent":"蓼沼高齢福祉課長","answer":"これの１つの比較というのも何ですけれども、西五反田のほうに今ケアホームという、同じ特定施設を使った施設整備をいたしましたけれども、こちらのほうの料金がやや高いということがありますので、これよりも低廉な料金ということを１つの目標にいたしまして。","voiceIndex":88,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"今、既に低廉な料金になっているという話がありましたけれども、結局はこれでもう止まりだという理解でよろしいのでしょうか。品川区はわしらの生活をどう考えているんだ。私は、改めて、国民年金でも入れるように、一般財源を投入して、所得の少ない方への減免制度、これ、ぜひ品川区が始めるべきだと、そして、ケアホームの利用料を下げるべきだと思うんですけれども、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"この利用料設定に当たっては、いろいろこの間、補正予算等の審議でもご報告、ご説明してきましたように、区としても、一定程度財源の助成といいますか、そういう形で措置をしていますので、区としての必要な支援、助成というものは実施しているものと考えています。","voiceIndex":90,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは減免制度をぜひつくってほしいということです。それについてのお考えがありませんでしたので、もう一度ご答弁いただきたい。なぜつくらないのか、ご説明ください。","respondent":"蓼沼高齢福祉課長","answer":"利用料の減免制度については特に考えてございません。受けられるサービスに対しまして適切なご負担をしていただくということで考えてあります。","voiceIndex":92,"id":"exchange-041"},{"speaker":"中塚委員","kind":"確認","question":"今、減免制度はなじまないというお話でしたけれども、答弁がなかったのは、これは区の政策判断だということでいいのか、確認させてください。特別養護老人ホームは、平成１７年１０月からいわゆる減免制度があるわけですけれども、なぜケアホームのほうはないのか。先ほど部長の答弁の中で、利用する方とされない方の不公平感のお話がありましたけれども、これはどういう意味なのか、教えてください。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホームについては、所得の低い方については、法律の制度上、補足給付という制度が設けられておりますから、この部分とケアホームは一緒にすることはできないということになろうかと思います。","voiceIndex":96,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"今一つ説明がよくわからないんですけれども、答弁の中で、利用する人としない方の不公平感、これはどういう意味なのかということを教えてください。例えば介護保険料というのは、４０歳になったらみんな支払いするわけですよね。皆が払っているのに、お金のあるなしで、入れる施設と入れない施設が生まれる。それこそ不公平じゃないかと思うんですけれども、どういう意味なのか、教えてください。","respondent":"木下福祉高齢事業部長","answer":"収入の多い少ないで、入れる人が限られるという部分については、これは品川区のほうとしても多様な選択肢を用意しようということで、この間、特別養護老人ホームでの基盤整備のほか、新しいニーズにこたえるためにケアホームというのを品川版で整備してまいりました。","voiceIndex":98,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"今、多様な選択とありましたけれども、今回、原小学校跡のケアホームを含めて、国民年金の方がケアホームを選択できると思いますか。私は多様な選択というのは全く実態を理解してないと思うんですけれども、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"例えば再三お話のあります国民年金のみで入れるということであるならば、身体レベルにもよりますけれども、特別養護老人ホームなどの選択肢があるということであります。","voiceIndex":100,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"国民年金の方は特別養護老人ホームという選択肢があるというお話でした。では、もう一つ、待機者数の実態から見てどうでしょうか。特別養護老人ホームの待機者数は雑駁に４００人、ケアホームの待機者数は３０人。結局、お金の少ない方はなかなか入れない。お金のある方は、簡単に言えば、すぐに入れる。これが区が言っている選択なんですか。教えてください。","respondent":"蓼沼高齢福祉課長","answer":"部長のほうで多様な選択肢ということでご説明申し上げましたけれども、特別養護老人ホームを希望されている方もいらっしゃいますし、ケア付きの高齢者住宅をご希望されている方もいらっしゃいます。これは世論調査の結果でも明らかになっております。","voiceIndex":102,"id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"国民年金の方がケアホームは選択できない。それは理解しているのかどうか、教えてください。それで、今、待機者数、いろいろ、るるありましたけれども、では、特別養護老人ホームとケアホーム、待機者数から見れば、どちらのほうが入りやすいですか。結局はお金のあるなしで差別をしている。ぜひ減免制度をやるべきだと思いますけれども、先ほどの質問いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"減免については、先ほどの繰り返しになりますけれども、部長が答弁申し上げたとおりです。","voiceIndex":104,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"短い時間でやりとりしましたけれども、結局国民年金の方は、とてもケアホームには入れないわけですね。なぜそのことを理解できないのか、私には全くわかりません。ぜひ一般財源を投入して減免制度を始めて、所得のあるなしで差別をつくる、これはぜひやめていただきたい。強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-047"},{"speaker":"原委員","kind":"質問・要望","question":"１９５ページのほうの高齢者住宅対策事業等について先にお教えいただきたいんですけれども、プレス発表資料によりますと、住まいの情報センター設置調査一式で５００万円ぐらいかなという形になっているんですけれども、全体で６,１００万円ですので、その辺のところの数字をもう少し、ほかの関係のところの、数字上で何がどうこうという形のほうをご説明いただきたいということと、それから。","respondent":"冨岡高齢事業課長","answer":"この中には、先ほどおっしゃいました住まいの情報センターということで、区のさまざまな住宅施策の中で、バリアフリー住まい館というのがありますが、これをベースにしまして、さらに高齢者の方の住宅問題について庁内で横断的に検討いたしまして。","voiceIndex":108,"id":"exchange-048"},{"speaker":"原委員","kind":"質問・要望","question":"というのは、一般の賃貸関係ですと、手数料をくれる場合もあるし、払う場合もあると伺っているものですから、その辺のところ、この２７０万円に関してお聞きしたいということと、あと、２点目、さっき東京都宅地建物取引業協会の話が出ましたけれども、そういったご高齢の方の要請ですと、それが税金の問題であったり、土地の境の問題であったりとか、賃貸だけではなくて。","respondent":"冨岡高齢事業課長","answer":"そういうのも含めまして、検討の項目に入れてまいりたいと考えています。","voiceIndex":110,"id":"exchange-049"},{"speaker":"原委員","kind":"意見","question":"そうしましたらば、あともう一つ。例えば税理士会ですとか。今までやっておられるのも非常によくわかっております。というのは、すごく助かっているという意見を聞きますので。その辺のところで、ほかに、単純な話としては、税理士会だけではなくて、弁護士会、司法書士会、行政書士会、その辺のどこかとの連携関係だけをもう少しお聞かせいただければと思います。","respondent":"冨岡高齢事業課長","answer":"現状におきましては、まだ情報センターというのはこれからつくるという状況ですから、当然そういう連携についても視野に入れていかなければいけないのかなと考えています。","voiceIndex":112,"id":"exchange-050"},{"speaker":"本間委員","kind":"質問","question":"私は１８７ページ、中国残留邦人等支援事業について、１８９ページ、やさしいまちづくり計画推進費について、１９３ページ、新就業システム推進事業ならびに高齢者生きがいづくり事業についてお伺いします。りんかい線につきましては、音声誘導装置、初めて措置される装置も伺っております。これについて、夜間延長すべきだという地元の声、商店街の声があるんですが、この経過について一言お知らせください。","respondent":"阿部都市計画課長","answer":"それを受けまして、区としては、まずＪＲの東京支社に対して、営業時間を従来どおり延ばしてほしいという要請を行いました。しかし、その後その結果としては、残念ながら、こたえられないという回答が来ております。","voiceIndex":115,"id":"exchange-051"},{"speaker":"本間委員","kind":"質問","question":"これは大井町だけでないかもしれません。ほかの駅でも同じような部分がないとも言えません。が、この件につきまして、一方では確かにいい手だてをしているかもしれませんが、逆に、地域の人たちの反感を買うようなものが平然として行われるようなことについて、強く、私たちも見守っていきますし、これからも粘り強く働きかけをお願いしたいと思います。ご見解をお願いします。","respondent":"阿部都市計画課長","answer":"委員ご指摘ございましたけれども、大井町については、丸井の跡に対してヤマダ電機が入ってくるような商業の活性化という面もありますし、あと、地域の商店街の活性化という面からも、非常に大きな問題だと考えていますので。","voiceIndex":117,"id":"exchange-052"},{"speaker":"本間委員","kind":"質問","question":"１９３ページの新就業システム推進費のところです。サポしながわとして、定年退職をして、そして、シルバー人材センターにお世話になるといいますか、シルバー人材センターの年齢に達するまでの約１０年間ほどの皆さんが対象になっているかと思いますが、この件の新就業システム推進事業の中身を、簡単で結構ですから教えてください。そして、どのような実績を上げられているのか、お願いします。","respondent":"冨岡高齢事業課長","answer":"求人件数が５０１件。一緒にマッチングといいますか、うまく合いましたのが２７２件です。平成１９年度につきましては、１月までですが、求職者数が５８５人、求人数が、ちょっと減りまして４７６件、マッチングのほうが２１９件です。","voiceIndex":121,"id":"exchange-053"},{"speaker":"本間委員","kind":"質問・要望","question":"やはり労働に対する報酬がきちっとできているかどうかという部分は大変大事なことであろうと思いますので、どうかその辺の目配りも今後ともきちっとしていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"おかげさまで、件数が非常に伸びておりまして、平成１７年度の実績が、延べ９,０００人参加されておりまして、平成１８年度は９,７００人、平成１９年度は、１月の段階で、９,５５０人ぐらいですので、恐らくこのままいけば、さらにまたご参加をいただいて。","voiceIndex":125,"id":"exchange-054"},{"speaker":"本間委員","kind":"意見","question":"品川区の事業では、いきいき脳の健康教室というような形の部分の施策もあるわけですけれども、いきいき健康マージャン広場が大変人気になってきているです。いずれ区で大会でもできるようにお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"全部ですと言われちゃうと、ちょっとあれなので、ポイントを教えてください。区という同じ経営主体のもとで、保育の専門家の知識と経験が動員できて、すばらしい施設だと思うんですけれども、小中一貫校６校構想だと思いますが、ぷりすくーる西五反田とか含めてかもしれませんが、区内の地域で、この辺で６園構想というのをしたらどうなのかなという思いがあるんですけれども、その辺についてお伺いします。","respondent":"福島長期計画担当課長、諸岡児童課長、小林保育課長、高橋幼保一元担当課長","answer":"私から、質問がありました品川区の次世代育成の全般につきましてご説明します。親育て、親育ち事業です。これについて、次世代育成の意味を含めて、力を入れていきたいと考えています。また、年次の計画の中では、弾力化も含めて、期間途中での入園の中で、できるだけ待機児を解消し、また、地域的なギャップにつきましては。区内に小中一貫校のような、区内全体への何園構想とかというのはいかがですかですけれども、保育園、幼稚園におきましては。","voiceIndex":129,"id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"そこをもっと、認証保育所との差というのがあって、こういう施策をしてくださったんですから、もっとバンと予算をつけて、認証保育所の方と認可保育園の方のお支払いする金額を限りなく狭めてあげるというのもいいと思うんですけれども、それはいかがでしょうかということが１点。１次に落ちた方の不安を解消させてあげることも大事だと思うんですけれども、いかがでしょうか。","respondent":"小林保育課長","answer":"そうした中で、多様な選択ということで、区としては、制度創設をしていきたいという考えがあります。それともう一つ、１次に入れない部分の、おっしゃるとおりです。今できる努力ということで、弾力化の適用も含めて、可能な限りの対応をしていく考えです。","voiceIndex":135,"id":"exchange-057"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問しますのは、１８６ページの社会福祉総務費の中のホームレス対策事業、それと、２２０ページの生活保護について、扶助費のほうについて伺いさせていただきたいと思います。ホームレス対策事業で、前年度について、自立支援センター品川寮という話がございました。その後どうなっているのか、お教えください。","respondent":"志村生活福祉課長","answer":"私どもが進めようとしている施設につきましては、今、渋谷区が千駄ヶ谷のところに自立支援センターを設けておりまして、これが来年の３月に５年が過ぎるということで、新しく品川につくる。こういう予定になってあります。","voiceIndex":138,"id":"exchange-058"},{"speaker":"大沢委員","kind":"質問","question":"平成２１年３月以降ということで、１００名規模のセンターができるということを今伺いましたけれども、品川区におきまして、次の生活福祉の保護のほうと関係してくるんですけれども、保護の方法の中での宿所提供施設ということで、１名入っておりますが、これはホームレスの方が入っているんでしょうか。それとも別の方が入っているんでしょうか。","respondent":"志村生活福祉課長","answer":"ですから、最初の質問の品川寮のほうですけれども、これは、最初、入所されるときは保護にはかかってございません。その中で、例えば病気になられたりとかとなりますと、医療費が払えないとなると、そこの部分で生活保護をかけていく。このような関係になってあります。","voiceIndex":140,"id":"exchange-059"},{"speaker":"大沢委員","kind":"質問","question":"保護の方法で、今、救護施設ということで、宿所提供施設ということで、ここには、住宅のない要保護者の世帯に対して住宅を提供するための施設で、家族用と単身用とありますと。住宅のない要保護者ということなんですが、住宅のないということは、これはホームレスとはまた違うんでしょうか。","respondent":"志村生活福祉課長","answer":"ただ、一般的には、例えば家賃を滞納されて、アパートを追い出されて、行くところがないとなりますと、こうした宿所提供施設のほうにと、私どものほうで窓口ではそのようなことに対応しています。","voiceIndex":142,"id":"exchange-060"},{"speaker":"大沢委員","kind":"質問・要望","question":"１００名程度ということで、自立支援センターができるわけですけれども、本来、生活保護というのは、居宅保護の原則というのがありますけれども、この施設というものは、居宅に当たるのかどうか。独自のご見解といいますか、広く一般的に通説となっている見解でよろしいので、聞かせていただきたいと思います。","respondent":"志村生活福祉課長","answer":"自立支援システムですけれども、今申し上げたとおり、これはほとんど保護にかかってございません。たまたまこの中でそういう必要が、病気等になられた場合だけ、そこの部分で保護をかけますので、ほとんどの入所者については、そういう意味で、生活保護の非該当であります。","voiceIndex":144,"id":"exchange-061"},{"speaker":"大沢委員","kind":"質問","question":"話がごちゃごちゃになってきましたので、整理しますけれども、ホームレスのほう、ちょっと聞いていてわからなくなりました。これは個室があるんでしょうか。それとも大部屋みたいになっているんでしょうか。","respondent":"志村生活福祉課長","answer":"ただし、一番新しい、私ども第３ブロックにできました世田谷寮ですけれども、大部屋１０人になってございまして、真ん中が廊下になって、片一方に５人ずつ、１段ベッドになってございまして、病院と同じようにカーテンで仕切られるような、このようなことになっていますけれども。","voiceIndex":146,"id":"exchange-062"},{"speaker":"大沢委員","kind":"質問・要望","question":"ことのよしあしは別であれ、居宅保護の原則という部分において、ホームレスの方の自立支援イコール施設ではなくて即アパートという、これは比較的敬遠されるのは、これは何ゆえかちょっと教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"私どものほうで現在緊急一時、それから自立支援施設を行ってありますのと同じように、ホームレス地域生活移行支援事業というのを東京都と共同で平成１９年度までやってまいりました。","voiceIndex":148,"id":"exchange-063"},{"speaker":"大沢委員","kind":"質問・要望","question":"前にもお伺いをいたしました生活保護費の不正受給という問題、前にも伺わさせていただきましたけれども、不正受給に対してどのように区は管理されているかということで、管理というか、確認をしているかということで、しているんですけれども、これ、例えば１つの例で、黙視でということで、きちっと制度のある生活保護費を払うことに対してのこちらのチェック。","respondent":"志村生活福祉課長","answer":"ただし、あくまでもこうした報告というのは義務づけておりますので、この辺についてはこれからも徹底してまいりたい、かように考えてあります。","voiceIndex":150,"id":"exchange-064"},{"speaker":"大沢委員","kind":"質問・要望","question":"医療、福祉に限っては、そういうカードを使うというのは無理かもしれませんけれども、こと食生活とか、娯楽は、あくまでも最低限度の生活を営む制度ですから、あまり華美に走るような娯楽があってはいけないと思いますけれども、こと生活に関して、チェックをする部分に関して、区からカードを貸与する。","respondent":"志村生活福祉課長","answer":"カードというお話、実は私、初めて伺ったものですから、生活扶助の、いわゆる支給現金にかわってということですか。ちょっと今、初めて聞きましたので、逆に言うと、それは決済できるのか。これは検討課題かと。","voiceIndex":152,"id":"exchange-065"},{"speaker":"市川委員","kind":"質問","question":"私のほうからは１８９ページのやさしいまちづくり計画推進費、それから、介護保険の５３５ページの地域貢献ポイント事業、それから、２１７ページの子育て支援事業、時間があったら２０９ページの児童相談事業について伺います。当事者参加というところをどういうふうに考えたらいいのかということをお聞きします。それから、推進計画を具体化する実行計画をつくるようになるのか。その辺もお聞きします。","respondent":"上山介護保険担当課長","answer":"それで、平成２０年度におきまして、そうした進め方も含めまして、調査研究をし、今後の具体化に向けて検討を進めていきたいと考えております。","voiceIndex":156,"id":"exchange-066"},{"speaker":"市川委員","kind":"質問","question":"進捗状況をチェックする推進会議のような機関が当然必要になると思うんですけれども、骨子案の１７ページの図で見ますと、やさしいまちづくり推進会議がその役目を果たすのかなとも受け取れるんですけれども、このチェックをする機関はどんなメンバーで構成されるようになるんでしょうか。教えてください。","respondent":"上山介護保険担当課長","answer":"やさしいまちづくり推進協議会のほうで事業計画自体の状況報告をさせていただいて、改善等があれば、反映させながら、この計画を推進していくことになりますけれども、そのメンバーといたしましては、改定委員会のメンバーの方もほとんどこちらの協議会のメンバーでございまして。","voiceIndex":158,"id":"exchange-067"},{"speaker":"市川委員","kind":"質問","question":"そうしますと、やさしいまちづくり推進計画とあまり変わらないということですね。実際にこの計画をつくったところとチェックをするメンバーが、実際にはそう変わりはないということなんでしょうか。","respondent":"上山介護保険担当課長","answer":"平成２０年度もこの計画の中で実施する予定で、重点地区を設定いたしまして、まち歩き点検等によりまして、課題の抽出および改善策の検討を行うということで、この部分も含んでの調査委託になっているわけですが、まち歩き点検等につきましては、実際に障害のある方々。","voiceIndex":160,"id":"exchange-068"},{"speaker":"市川委員","kind":"質問・要望","question":"推進会議とか、会の代表が入るということは否定することではないんですけれども、障害者でないとわからないバリアもあるんじゃないかなと思いますし、公募で中に入って自分の意見を言いたいという方もいらっしゃると思いますので、関心のある人が入れるための区民公募の枠というものをぜひ設けていただきたいと思うんですけれども、ご見解はいかがでしょうか。","respondent":"上山介護保険担当課長","answer":"平成２０年度に実施する予定でおります重点地区のケースの中で、今、お話しいただいたことも含めて検討してまいりたいと思います。","voiceIndex":162,"id":"exchange-069"},{"speaker":"市川委員","kind":"質問","question":"次の質問に移ります。５３５ページの地域貢献ポイント事業について伺います。ボランティア参加者の目標というんでしょうか、ここに１,０００人となっているんですけれども、まずこの根拠について伺います。それと、どことの協議において、またどれぐらいの期間を経てこの計画を進めてきたのか、課題とか留意点、効果等、その辺のところはどうだったんでしょうか。お聞きします。","respondent":"蓼沼高齢福祉課長","answer":"モデル的に街のコンシェルジェで、昨年末から今年１月にかけて一定のモデル事業実施をしてきまして、それのまとめを、効果の検証を今しつつあるところです。","voiceIndex":166,"id":"exchange-070"},{"speaker":"市川委員","kind":"質問","question":"品川は、ボランティア参加対象をおおむね６０歳ぐらいからとして、区内の共通商品券とも交換できる。こういう事業内容になっているんですけれども、品川の場合は、団塊世代の社会参加の位置づけがとても強いように思えるんですけれども、なぜ稲城市の方法をとらなかったのか。大きな理由は何なんでしょうか。教えてください。","respondent":"蓼沼高齢福祉課長","answer":"品川区の場合は、むしろ保険料については、介護保険制度の中で、保険料の運営の中で対応すべきものと考えておりまして、そういう意味では、対象者を、特に第１号被保険者と限定せずに、幅広く、おっしゃるように、団塊の世代も含めて、幅広い高齢者の社会参加ということを目的に。","voiceIndex":168,"id":"exchange-071"},{"speaker":"市川委員","kind":"質問・要望","question":"ちょっとまた伺うんですけれども、さわやかサービスの有償ボランティアと中延のＮＰＯの事業との線引きというところがちょっとよくわからないんですね。教えていただきたいということと、それから、この事業の実施期間は、いつから始まって、いつまでするのかとか、それから、事業の検証を途中でされるということがあるのか、その辺をお聞きします。","respondent":"蓼沼高齢福祉課長","answer":"４月以降、事業を実施するわけですけれども、ポイントがたまり次第、随時換金をして、寄附あるいは商品券に交換をしていただくということで考えているところです。","voiceIndex":170,"id":"exchange-072"},{"speaker":"市川委員","kind":"質問・要望","question":"次の質問なんですが、２１７ページの子育て支援事業について、まず入園予約制度について少し伺います。入る園児の年齢によって職員の配置というのは変わってくると思うんですけれども、職員配置が決定した後に入園希望者を選択するのか、それともその逆で、子どもに合わせて職員数を変更するのか、この辺をどういうふうに考えているのかを伺います。","respondent":"小林保育課長","answer":"そうではなくて、通常の月次の入園選考は、その入園選考枠の中で、緊急度の高いものから対応してまいります。","voiceIndex":172,"id":"exchange-073"},{"speaker":"若林委員","kind":"質問・要望","question":"１８７ページの民生委員経費、１９１ページの花づくり助成金、４３９ページの特定保健指導、３点伺います。花づくり助成金のほうは、たしか春、秋、年２回、区内２カ所でやられておりますけれども、今後、地域的な偏りというところが、花をお好きな高齢者の方からお話が出ておりましたので、もう少し全区的な展開というものはお考えはあるかどうかということをお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長、原国保年金課長","answer":"民生委員活動に関するお尋ねですけれども、今年度と平成２０年度とでは、基本的に活動内容はそう大きくは変化はございません。花づくり助成金ですが、これは高齢者クラブ連合会に助成をしている助成金の１つでございまして、潤いのある生活ということで、菊づくりの講習会をしたり。具体的には、栄養士についても、この４月から事業が具体的に実施するところで、一般賃金ということで雇い上げていきたいと考えています。","voiceIndex":177,"id":"exchange-074"},{"speaker":"若林委員","kind":"質問・要望","question":"花づくりの方は今後の展開をお聞きしましたので、事業内容は結構です。もう１回その点、お考えを、ぜひ拡大をしていただきたいという意味で聞いておりますので、お答えいただきたいと思います。今のご答弁で、仕事がまた、３年に１回の大きな事業が出てくるというご答弁だったと思うんですが、そこら辺の関係性をお聞きしたいと思うんです。この点をもう１回確認します。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長、原国保年金課長","answer":"花づくり助成の今後の部分ですが、この事業は、ご案内のとおり、高齢者クラブ連合会に助成をしているものですので。先ほど私が申し上げました実態調査につきましては、１９５ページに、高齢者相談等事業という事業がございまして、民生委員は、区の要綱で。そこまでの間に、先ほど申し上げました、業者との連携等の中でしっかりとした体制を組んでいくということでいきたいと考えています。","voiceIndex":181,"id":"exchange-075"},{"speaker":"若林委員","kind":"確認","question":"時間が使い方がまずかったので、特定健診だけ。これは、いわゆる改善の率が下がると、一般財源等からの繰入金を増やさなければいけないと、そういう仕組みになって、保険者がこの事業にしっかりと取り組まなければいけないということを１点確認させていただいて、今後の取り組みをしっかりとお願いしたいと思います。","respondent":"原国保年金課長","answer":"委員指摘のとおり、平成２４年に予定されておりますけれども、後期高齢者支援金、こちらのほうがインセンティブが働くということで、実施の率によって額が変わってくるという形になってあります。","voiceIndex":185,"id":"exchange-076"},{"speaker":"高橋委員","kind":"意見","question":"１９１ページの高齢福祉費についてと、ちょっと全般的なこと、それからあと、１９４ページの障害者福祉全般のことでお尋ねします。１９１ページのほうは、高齢福祉課の金庫からお金がなくなったという、預かり金紛失についてのことで、その後のことをお尋ねします。事故防止対策委員会が今後の対応などを発表されたんですが、警察に捜査を１２月３日に依頼して、その後、捜査はどうなったのか。","respondent":"桑村総務課長","answer":"それに応じて研修等も、お金を扱う方につきましては、会計管理者のほうで研修に入っているものです。今後、警察等の捜査等になりまして、また新たな考え方、あるいは、新たな事実が発見されれば、それなりに対応してまいりたいと考えているところです。","voiceIndex":188,"id":"exchange-077"},{"speaker":"高橋委員","kind":"質問","question":"どのような研究がなされ、社会福祉法人のほうでその後、雇用の実績といいますか、それから、来年度の雇用の予定など、お話しいただければと思います。社会福祉法人で協議をして、雇用を促進するための方策をとられているというお話も伺ったので、よろしくお願いいたします。","respondent":"蓼沼高齢福祉課長","answer":"昨年からこの間にかけてですので、具体的に各法人で、それぞれ今、検討していますが、何か制度的なものが活用できないかとか、あるいは、ハローワーク等との連携をもう少し密にして、直接的に雇用に結びつくような方策がないかとか、そういうようなことを今検討していますので。","voiceIndex":190,"id":"exchange-078"},{"speaker":"高橋委員","kind":"質問・要望","question":"障害児の出生から就学までの療育の情報を集約した、一貫して支援をするセンターですね、それをコーディネートするような施設を、ケアプラン等を作成して、そういったような施設を今後設立していただきたいというお話をしたのですが、そのような役割を平成２０年度の中では、どんなところで行っていかれるのでしょうか。","respondent":"高橋障害者福祉課長","answer":"将来の療育センターみたいなところということの現在の状況ですが、１９９ページにあります療育相談支援事業ということを、まず初めに、子育て支援センターから障害児の専門相談を移行して、その後、それぞれの療育事業がありますので、連携をしながら、その施設を含めまして。","voiceIndex":192,"id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"障害者福祉の費用の全般のことでお尋ねしたいんですが、空室保障、また空床、その制度についてご説明をいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"現在、１２月末に、厚生労働省案として、施設側に対する保障については来年度以降どうやっていくのかという通知はありますが、具体的にはまだ検討中ということで、現在も９０％保障を行っているものです。","voiceIndex":194,"id":"exchange-080"},{"speaker":"高橋委員","kind":"質問","question":"品川区がそれをやるかどうかというのは、品川区が判断するんでしょうか。今、９０％保障をするかどうか、来年度からは未定だとおっしゃったんですが。","respondent":"高橋障害者福祉課長","answer":"そのところについてどういうふうに動くかというのはわかりませんが、品川区としては、９０％保障については実施を継続していきますということです。","voiceIndex":198,"id":"exchange-081"},{"speaker":"高橋委員","kind":"意見","question":"今お話にあった９０％保障のことと関連しまして、私、開園式にも出席させていただき、その後、視察もさせていただいたんですが、児童デイサービスの発達障害療養施設の品川児童学園、こちらが区内の発達障害児の相談・療育の機関となっているんですが、こちらにどれぐらいの障害を持った方が相談・療育に訪れているのか、ちょっとお尋ねしたいんです。最近で結構です。","respondent":"高橋障害者福祉課長","answer":"品川児童学園で行っています発達障害者の児童デイサービス、コンパスに通所している方につきましては、１９人です。","voiceIndex":200,"id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"定員が１日２０名ということで、毎日１９人行かれているとすると、指導とか大変だと思うんですが、こちらで毎日それぐらい訪れているんでしょうか。","respondent":"高橋障害者福祉課長","answer":"この方については、１９人が登録ということで、療育ですので、週１回とか２回ということで、それぞれの時間帯に合わせて個別の対応、また、グループ活動に参加していただいているものです。","voiceIndex":202,"id":"exchange-083"},{"speaker":"高橋委員","kind":"質問・要望","question":"ほかの施設も、障害者自立支援法の中では、空床保障が適用されると思いますので、よろしくお願いしたいと思います。これは、保障している場合は、都のほうの補助金も一緒に給付の中に入っているんでしょうか。","respondent":"高橋障害者福祉課長","answer":"９０％のところの部分につきましては、国、都、区ということで、３者で負担をしています。それから、実績につきましては、実際上のだれがどこに通所しているかというのは私どもでわかりますので、その辺はきちっとチェックさせていただいて、給付しているものです。","voiceIndex":204,"id":"exchange-084"},{"speaker":"高橋委員","kind":"意見","question":"今のお話はそれで結構です。先になりますが、２１７ページのところで、先ほどのご説明もあったんですが、就学前乳幼児教育基盤整備とありますが、平成１９年にはこれがプログラムの策定という形であって、プログラムの策定が完了したのではないかと思いますが、プログラムの策定の内容について簡単にご説明いただければと思います。","respondent":"高橋幼保一元担当課長","answer":"そして最後に、５章におきましては、今後、それらを実施するに当たりましての、乳幼児教育実践に当たっての留意事項ということで記載しています。","voiceIndex":206,"id":"exchange-085"},{"speaker":"高橋委員","kind":"質問","question":"それを受けての基盤整備、先ほど課長のほうから、時間がなかったみたいで、あまり詳しくは教えていただけなかったので、幾つか具体例を挙げていただければと思います。平成２０年の予算の中の教育基盤整備というところで。","respondent":"高橋幼保一元担当課長","answer":"先ほどは平成１９年度の中でのプログラムの内容でございまして、では、平成２０年度はどうするかということにつきましては、平成２０年度につきましては、３章に書かれています保育・教育課程の中に家庭支援というところがありますが、その内容を、保育者側に立った。","voiceIndex":208,"id":"exchange-086"},{"speaker":"高橋委員","kind":"質問","question":"では最後に、ページは２１１ページに戻ってしまうんですが、入園予約の話ですが、先ほど、公立のほうでは弾力的な定員の運用ということですが、他区の私立保育園の経営者の方にお会いしたときに、私立は品川はどうするんだろうなんていう話があったんですが、区として、私立保育園のほうにも弾力的にそういった予約制度をというようなことはどうなんでしょうか。","respondent":"小林保育課長","answer":"私立保育園も、待機児解消にご協力いただく観点から、既に相当数の弾力化の運用をしていただいております。したがいまして、今回新たにスタートいたします育児休業の計画に基づいた云々という意味での枠につきましては、とりあえず既存区立保育園での対応です。","voiceIndex":210,"id":"exchange-087"},{"speaker":"本多委員","kind":"質問","question":"１９３ページですとか、５３４ページにあります介護予防全般について、質問します。これまでの取り組みについては、どう検証されてきたのかというのが、先ほど出ておりまして、平成２０年度の予算を見ますと、全般的に、介護予防の予算が増額となっております。それから、新規事業の生活機能評価、いきいきうんどう教室、地域貢献ポイント事業、概要でいいので、教えてください。","respondent":"蓼沼高齢福祉課長","answer":"平成２０年度についても、その評価につきましては、介護予防システム推進事業の中で検討してまいることとしています。児童保健事業部と、あるいは、福祉高齢事業部内でも、高齢福祉課、高齢事業課は連携を図りながら事業の充実に努めているところです。","voiceIndex":213,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"このいきいき筋力向上トレーニングというのは、おもに高齢者の転倒防止とか、お元気な方でも転倒をきっかけに急に老け込んだりすることを防止したりするとか、いきいきコースですとか、はつらつコースですとかいろいろあるんですけれども、１６人ずつのグループに分けられると思うんですが、予算書で１７６人ということで、平成２０年度の進め方について、教えていただきたいんです。","respondent":"冨岡高齢事業課長","answer":"その中身は、今まで使っていたマシンを使うのではなくて、総合型のプログラムという形で、マットとか、バランスボールとかを使いまして筋力のトレーニング、維持に努めるということとあわせて、付加的に口腔ケアとか、栄養改善の講義なども含めて。","voiceIndex":215,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"全戸配布じゃなくて、２万部から３万部ということなんですけれども、ほかの事業はどのように周知をされているのか、その辺を教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"介護予防事業、メニューはたくさんありますけれども、いわゆる特定高齢者、あるいはそれに準ずる方、チェックリストでスクリーニングをする、それで介護予防事業が必要だという方たちは、私たちども高齢福祉課で対応しております。","voiceIndex":217,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３９７ページからの国民健康保険と、４７３ページからの後期高齢者医療制度について、質問をさせていただきたいと思います。その内容と、区民への影響などをお聞きしたいと思います。１年間、一応凍結となりますけれども、その人数と、そうなる理由を教えていただきたいと思います。この１人当たりの保険料、１９９１年と今年、あわせて教えていただきたいと思います。","respondent":"原国保年金課長","answer":"年金天引きの人数ですけれども、こちらについては、これから数値をもとに年金の情報をもらいながら実施していくところですけれども、私どものほうでつかんでいるところでは、約１万１,０００人ぐらいのところで見ているところです。","voiceIndex":220,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、凍結というか、２割負担を実施しないようにということで、区のほうからも、声を大きく挙げていただきたい。これは要望させていただきたいと思います。この方は、年金が非課税から課税になった方だと思うんですけれども、この方が平成１７年度、平成１８年度、平成１９年度、平成２０年度と、国民健康保険料がどういうふうに変わってきているのかということについて、教えていただきたいと思います。","respondent":"原国保年金課長","answer":"国民健康保険については、いろいろな形で、低所得者の対策を講じております。保険料については、７割減額、あるいは、５割減額を実施しておりますし、均等割のみの世帯も、国民健康保険の中では４３％ということで、そういったような形の状況です。","voiceIndex":222,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この資格証明書というのは、国民健康保険法の施行令の中で、病気になったり、生活が困窮していれば発行できない、交付しないということになっていますけれども、ここのところを確認された上で出されているのかということを、２番目にお聞かせください。それから、私は改めて、資格証明書を発行している世帯の生活実態を調査をすべきだと思うんですけれども、あわせてお聞かせください。","respondent":"原国保年金課長","answer":"もう１点、生活実態につきましては、資格証明書を出したら出しっ放しということではなくて、その後も電話連絡等々をしながら、相談に応じながら実施しています。","voiceIndex":224,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"資格証明書を、特別な事情があるときは発行してはいけないというのがあって、病気があるときと、世帯主がその事業を廃止し、または急死したことなどの貧困に窮している方のところには発行してはならないということになっていると思うんですけれども、ここのところは確認して、発行しない状況になっているのかということをお聞きしたので、そこのところを、改めてお聞かせいただきたいと思います。","respondent":"原国保年金課長","answer":"そういう意味では、滞納しているときに、いろいろな形で督促状を出させていただいたり、納付の形で電話等をするという交渉の中で、例えば、こういう状況であるとか、そういったことをお話の中でするわけですから、そういったところを配慮しながら発行しています。","voiceIndex":226,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それが一つです。こういうほんとうに最悪の制度だと思うんです。自民党市議団のほうでも、岐阜の大垣市では、自民党市議団の提案で、廃止を求める意見書が出されるという大きな全国的な声が挙がっているという状況なんです。このところでは、一つは、説明会を、ぜひ、してほしいということで申し入れをさせていただいて、それにこたえていただいて、今、説明会がされているところです。","respondent":"原国保年金課長、冨岡高齢事業課長","answer":"法令にのっとった形で運用をしていきたいと考えているところです。説明会につきましては、今まさに実施をさせていただいておりまして、これから何回かありますので、その辺の状況を見ながら、今後については対応を考えてまいりたいと考えています。","voiceIndex":228,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、７５歳以上の人を、医療の中身でさらに差別をするということはやめるように、区のほうからも働きかけていただきたいと思います。持続可能な医療制度ということで言われていますけれども、欧米に比べると、そもそもすごく低い医療費がありますので、そこのところを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-096"},{"speaker":"阿部委員","kind":"質問・要望","question":"認証保育所助成についてです。認証保育所助成を、ということで、昨年の一般質問の中で要望いたしまして、早速に実現していただいてありがとうあります。先ほど、認証保育所の保育士にも配付をされるということでしたけれども、認証保育所に対しても、保育課程、教育課程について、品川区が足並みをそろえるように求めていくのか、また、園の交流なども行っていくのか、そのあたりのことを教えてください。","respondent":"高橋幼保一元担当課長","answer":"今、お尋ねの認証保育所と、今回、作成するプログラムの関係ですけれども、品川区は、品川区の就学前の子どもたちに対して、施設にいようが、家庭にいようが、すべての子どもに対して質の高い乳幼児教育を提供していきたいというところでございまして、認証保育所におきましては。","voiceIndex":234,"id":"exchange-097"},{"speaker":"阿部委員","kind":"質問","question":"区のほうで願ってということなんですけれども、どの程度、保育内容等に反映してもらえるのか、また実際に、事業として交流なども行っていくのか、そのあたりを教えてください。","respondent":"高橋幼保一元担当課長","answer":"そのことについては、また認証保育所等について、保育課長と話しながら情報交換をしながら、情報を提供しながら進めていくのが、今の我々が求めている乳幼児教育の推進につながるのではないかと考えているところです。","voiceIndex":236,"id":"exchange-098"},{"speaker":"阿部委員","kind":"質問・要望","question":"それから次に、２１２ページの児童福祉施設入園事務なんですけれども、本年も保育園の入園に関しまして、保護者の方、特にお母さん方は、入園を求めてさまざまに、区の窓口に来てはいろいろと質問をしたり、手続をしたりされていましたが、その中でよく耳にしたのが、なかなか窓口での説明がわかりづらいとか、説明する方によって、どこまで教えてもらえるかが違っているというようなこと。","respondent":"小林保育課長","answer":"現在あるマニュアルを見直したり、ご提案のありました、いわゆるよくある点のＱ＆Ａ、そういったものをあわせて整備し、対応の徹底に努めてまいりたいと思います。","voiceIndex":238,"id":"exchange-099"},{"speaker":"阿部委員","kind":"質問","question":"２１７ページ、子育てプランの作成。この育児休業からのスムーズな保育の接続ということは、私が議員なる前から、ぜひこういったことがあればいいなと思っていた内容でして、これができただけで、私は議員になったかいがあったと大変嬉しく思っております。失ったものも多いですけど。とにかく、これはいいかなと。慣らし保育について、伺いたいと思います。いかがでしょうか。","respondent":"小林保育課長","answer":"ただし、４月１日ジャストの入園の場合に、３月中の慣らしは、状況によっては、ちょっとできない場合もありますので、その辺は、保育園の現場の状況に応じて、お母さん、お父さんと相談して決めてまいりたいと思います。","voiceIndex":240,"id":"exchange-100"},{"speaker":"阿部委員","kind":"質問・要望","question":"こういった高い水準のサービスですとか、あるいは、さまざまなメニューというものは、ぜひ、ほかの地域でも広がってもらいたいと考えていますし、そのことが、品川区への集中を緩和することになると思いますので、ぜひ、他区に、あるいは国に対しても、さまざまなサービスを、品川区がやってよかったと思うものは、ほかでもやるように誘導するような働きかけをしていただきたいと思うんですが。","respondent":"小林保育課長","answer":"もちろん、待機児というのは、いろいろな自治体がそれぞれ状況に応じてはやっているものの、その状況を改善するために、よりよくしていく取り組みが必要と考えておりますので、品川区の力のある限りは、その状況を他区に情報発信するなどして、地域として。","voiceIndex":242,"id":"exchange-101"},{"speaker":"阿部委員","kind":"質問","question":"スタンプがたまったら、例えば、今度は保育園の試食サービスなんかに無料で参加できるとか、あるいは、場合によっては、地域内の商品券なんかでもいいかもしれませんが、そういった形で、まずは足を運んでもらうというような工夫をしてはどうかなと思うのですけれども、いかがでしょうか、お考えを教えてください。","respondent":"諸岡児童課長","answer":"登録をしていただくことによって、関係をつくっていただいて、さまざまなサービスにつなげていきたいというように考えております。もちろんそれ以外のインターネット等についても、広報、ＰＲには、今後も努めていきたいと考えています。","voiceIndex":246,"id":"exchange-102"},{"speaker":"阿部委員","kind":"提案","question":"残り三つもあるんですけれども、その中から、出会いの湯について。ただ、６,０００万円という予算は、ちょっとどうかなという気がするんです。同じページの例えば生きがいづくり事業、全部合わせても２００万円です。これは、今後に対する提案でもありますけれども、あくまでもメニューの一つとしての予算配分のバランスというのを考えられてはいかがかと思いますが、いかがでしょうか。","respondent":"冨岡高齢事業課長","answer":"しながわ出会いの湯ですが、これにつきましては、銭湯が始まる前に、高齢者の方がお楽しみプログラムを実施する、そしてそれにあわせて、その後に、登録証を持った方が無料で引き続き銭湯にお入りいただくという事業で、すべて委託をしているものでございまして。","voiceIndex":248,"id":"exchange-103"},{"speaker":"松澤委員","kind":"質問","question":"３款民生費、１項社会福祉費、２目高齢福祉費の、１９５ページ、住宅用火災警報器設置促進事業についてと、同じく２項児童福祉費、２０９ページになるんでしょうか、各種保育事業助成に関連して、保育ママについてお聞きしたいと思います。１点目ですけれども、先ほど、午前中にもご質疑があったと思うんですけれども、よく聞こえなかったものですから、改めてお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"ただ、絞り込みが、実際に世帯構成とか、介護保険料所得段階がマッチングするのが難しい部分がありまして、なかなか正確な把握がしにくいという点がありますけれども、そういった中でも、１,２００人程度を見込んで、それを平成１９年度、平成２０年度。","voiceIndex":251,"id":"exchange-104"},{"speaker":"松澤委員","kind":"質問","question":"それに、品川区が助成するわけですから、今までの普通の助成制度と違って、平成２２年４月１日には、この対象家庭にはすべて火災警報器がつかなくてはいけない、つけるという意気込みでやるんだというふうに、私は思っているんです。品川区が要綱をつくったからには、設置しなくてはいけないという義務感があると思っているんですけれども、その辺の考え方はいかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"設置に対する考え方ですけれども、火災警報器の設置につきましては、近年の、火災による高齢者の死亡が増加しているという状況を背景に実施に入ったものです。","voiceIndex":253,"id":"exchange-105"},{"speaker":"松澤委員","kind":"質問・要望","question":"平成２２年３月３１日になって、まだたくさん残っているなんていうことがないようにお願いしたいと思います。品川区の予算書に出なくなって五、六年になるんですかね。新聞報道を見ますと、２００８年度からやるというところと、平成２２年度から実施するというところと、新聞２社を見ただけではなかなかわからないんですが、もしわかっていたら、その辺の情報をしっかりと教えていただきたいと思います。","respondent":"小林保育課長","answer":"その実施年度につきまして、私どもが承知しておりますのは、厚生労働省は平成２２年度からの実施を目指していると聞いております。","voiceIndex":255,"id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"この問題は、保育ママになる人を拡大するというだけではだめだと思っているんです。この制度そのものは日本全国で実施されるわけですから、地方ではいいですけれども、品川区のような大都市の中では、やはりその家庭の中で保育室６畳がなくちゃいけません、２階だったら、２方向から避難路がなくちゃいけません、これがネックになっていると思うんです。","respondent":"小林保育課長","answer":"したがいまして、この制度を考えていくとすれば、今後の可能性として、地域の子育てという観点から、場合によると、私どもが持っております保育園も含めた施設サービスでやっていただく、人のバックアップがどれだけあわせてやっていけるか、その辺の条件整備によって。","voiceIndex":257,"id":"exchange-107"},{"speaker":"松澤委員","kind":"意見","question":"この問題は、家庭保育か、社会保育かということで、大分やり合った経験がありますので、この制度がまた復活して、保育ママが復活するのを楽しみしていますので、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":259,"id":"exchange-108"},{"speaker":"山路委員","kind":"質問・要望","question":"２０１ページ、障害者就労訓練事業の中から、作業所ネットワーク支援事業について、２０９ページ、子どもすこやか医療費助成事業に関連して、お伺いをいたします。","respondent":"高橋障害者福祉課長","answer":"カタログ販売とか、ネット販売を考えていますので、どういうものがいいのかということで、印刷費、それからネットにどういうふうな形で取り上げるかという検討費用です。","voiceIndex":261,"id":"exchange-109"},{"speaker":"山路委員","kind":"提案","question":"その模様を品川区にも提案いたしまして、臨海斎場ができたときに、骨つぼを製作するということで取り組んでこられた。しかし、作業がはかどるかどうかといろいろな問題を抱えながら、ここまで来たんです。新しくここで組まれるということで、今、説明をお伺いしましたけれども、私は非常に喜んでいるわけですが、その後の状況と、その辺の経緯をちょっと聞かせていただけますでしょうか。","respondent":"高橋障害者福祉課長","answer":"賃金倍増のことで、この取り組みを考えているものなんですが、実際上、厚生労働省の中で、工賃の月額について、授産施設については、大体１万２,０００円程度、福祉工場については１０万円程度というような状況が出ています。","voiceIndex":263,"id":"exchange-110"},{"speaker":"山路委員","kind":"質問","question":"ここで「ナイスサティ」という事業を土曜日に行われているということを、当時、お伺いしたんですが、その後の状況について、皆さんが楽しくやっていらっしゃるかどうか、ちょっとお伺いしたいんです。","respondent":"高橋障害者福祉課長","answer":"五反田にあります精神障害者の生活支援センター「たいむ」ですが、土曜日も月２回開けまして、そこに参加していただき、オープンスペースにも参加していただくということとか、クラブ活動に参加していただくこととかで、精神障害者が外に出るということも一つの訓練の場ですので。","voiceIndex":265,"id":"exchange-111"},{"speaker":"山路委員","kind":"確認","question":"国の流れでは、毎年２,０００円ずつアップしているですが、品川区も、当然、ここ数年毎年２,０００円ずつアップされているんですよね。ちょっと確認をしておきたいと思います。","respondent":"高橋障害者福祉課長","answer":"先ほど申しましたとおり、工賃の平均が１万２,０００円ですので、一挙に２,０００円というと、１万４,０００円を毎年というと、ちょっと厳しいものがありますが、その辺の努力はさせていただいていますので、よろしくお願いいたします。","voiceIndex":267,"id":"exchange-112"},{"speaker":"山路委員","kind":"質問","question":"地域の中で、就労ができるという、さらにネットワークということで、今後、期待をしておりますので、どうぞよろしくお願い申し上げます。もう１点は、子どもすこやか医療費助成事業に関連いたしまして、昨年の１０月、区長の英断によりまして、所得制限を撤廃して中学３年生までにしました。問題提起として、ちょっとお伺いをいたします。","respondent":"小林保育課長","answer":"ただ、聞いた、聞かないということではあれですので、何か字でもらえませんかということで、簡便になるようにということで様式を定めております。それを提出していただく形で進めております。","voiceIndex":269,"id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"２１７ページのオアシスルームと児童センターについて、お聞きします。各種助成金の中で、障害者７団体がありますけれども、新規に加盟している方が、最近どういう傾向にあるのかというところを教えてください。そのためには新規採用がずっとされてなかったんですけれども、今後、どういう形で新規採用をされて、今までのノウハウを伝えていくのかというところをお聞きしたいと思います。","respondent":"小林保育課長、高橋障害者福祉課長、高橋幼保一元担当課長、榎本人事課長","answer":"その子どもの居場所によって、ストレスがというお話でございましたけれども、それは、子どもの状況を第一に、集団保育が望ましいときは、そのように。例えば脳梗塞とか、糖尿病、高齢で難聴とかということで、視覚障害者、また肢体不自由児のほうに入るとか、身体障害のほうの友和会に入るとか。ただ、乳児クラスといいますか、３歳、２歳、１歳については、１歳、２歳につきましては、やはり設置基準等の中で。ただし、この間、職員の世代の部分がありますので、保育士での補充ということを、今、検討しています。","voiceIndex":272,"id":"exchange-114"},{"speaker":"西本委員","kind":"質問・要望","question":"知らないのか、なるべく入っていただきたいと思っているんです。いろいろ、団体の方々は一生懸命されているので、もしかして１人で悩んでいる方がいるかもしれない、そういう方がいらっしゃったら、例えば保健所等々でそのつなぎ役を、ぜひしていただきたいということで、要望をしておきたいと思います。ですから、０歳、１歳、２歳のほうに定員をシフトはできないんですか、ということです。","respondent":"高橋障害者福祉課長、小林保育課長","answer":"いろいろな場面につきまして、つなぎ役として、今後もＰＲを継続して努力しますので、よろしくお願いいたします。４歳、５歳児を幼稚園へシフトすることによって、その分を乳幼児に回す可能性につきましては、個々の状況に応じて対応を考えてまいりたいと思います。","voiceIndex":277,"id":"exchange-115"},{"speaker":"須藤委員","kind":"意見","question":"１８７ページの施設系サービス事業者の経営・質の向上支援ということなんですが、このことについて、今、いろいろな福祉施設で管理委託をしたりしていますけれども、そのあたりとの連携はどうなっているのか。そのあたりはどういうふうに関連してくるのか。居宅介護ということを中心にしていたと思うんですけれども、それが減ってきているのはなぜか、そのあたりを聞かせてください。","respondent":"蓼沼高齢福祉課長","answer":"介護保険の給付のほうは、小規模多機能にしても、グループホームにしても、平成１８年度から地域密着は導入されたわけですけれども、この制度の変わり目にあって、予算計上していたよりも、グループホームについてもまだ整備が進まないとか、地域密着についても。","voiceIndex":281,"id":"exchange-116"},{"speaker":"須藤委員","kind":"質問","question":"１８９ページの福祉有償運送運営協議会、２１万円というのは、どういうメンバーで、どういう会議をやるのか教えてください。それから、１９３ページの新就業システム推進事業、これはハローワークとか、シルバー人材センターといったものとの関係はどういうふうになるのか教えてください。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"委員の構成といたしましては、学識経験者、それから、地域住民利用者の代表、地域ボランティアの代表、関係交通機関、主にタクシー事業者等の代表等から構成されているものです。新就業システム推進事業ですが、まず、ハローワークとのかかわりですけれども、常に情報交換しているということと、年に２回の合同面接会というのをきゅりあんでしています。","voiceIndex":283,"id":"exchange-117"},{"speaker":"須藤委員","kind":"質問","question":"１９３ページの新就業システムというのは、ハローワークと、シルバー人材センターと一緒になってやっていく仕事として考えていいのか、どうか。それだけ教えてください。","respondent":"冨岡高齢事業課長","answer":"シルバー人材センターは、当然、６０歳からの生きがいの就労ですので、その部分については、人材をお互いに紹介し合いながら選んでいただくように、同じ場所ですので、こういう仕事の仕方はどうでしょう、それとも正規で働きたいですかと、こういうような形で。","voiceIndex":286,"id":"exchange-118"},{"speaker":"須藤委員","kind":"質問","question":"１９３ページの介護予防・シニア活動拠点運営費ですが、３カ所、どこで、何をするのか教えてください。それから、同じく新予防給付マネジメント事業、何をする事業か教えてください。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長","answer":"介護予防・シニア活動拠点運営費ですが、これにつきましては、しながわシニアネットの拠点です関ヶ原と、山中いきいき広場、それから荏原いきいき倶楽部、この３カ所を活動拠点としているものです。介護報酬として、区が報酬を歳入して、１９の在宅介護支援センターと、一部、民間の居宅支援事業所に、プランの作成経費として支出をしているものです。","voiceIndex":288,"id":"exchange-119"},{"speaker":"須藤委員","kind":"質問","question":"介護予防等は、ほっとサロンと一緒にやっている事業として見ればいいかなと。それでいいか、どうか。というのは、高齢者が多くなってきて、施設も多くなって、目的も、入所の希望も多くなっていますというお話をされているので、東京都だけではなく、そういったところの調整もここでやられる、あるいはまた、回数も増やしていったらいいんじゃないかと思うんですが、そのあたりのお考えを教えてください。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長","answer":"こちらにつきましては、区の事業でありますいきいき脳の健康教室でありますとか、先ほど、出ました、筋力向上トレーニングですとか、パソコン教室、そういったものを実施する場所として使わせていただいております。そういう施設サービス、あるいは在宅も含めて、その方にどのようなサービスが適切なのかということは、在宅介護支援センターのほうの役割かと考えております。","voiceIndex":291,"id":"exchange-120"},{"speaker":"須藤委員","kind":"意見","question":"国民健康保険とか、後期高齢者医療制度、それから介護保険、いろいろ制度が変わってきているんですが、国民健康保険事業については、区民生活事業部が対応しますよね。介護保険、後期高齢者医療制度は１万６,３００人、２万５,０００人と、人でカウントをしているんだけれども、このあたりもそろえていったほうがいいんじゃないかと思うんですけれども、仕組みでだめだというのかどうか。","respondent":"原国保年金課長、日下部企画財政課長","answer":"今後の実施に当たりましても、健診、あるいは保健指導といったところは、国民年金課だけででききれるものではございませんで、今後の扱いについても、健康課サイドと連携を図りながら、区民の健康増進に努めていくところです。例えば、単純な例でありますけれども、お１人の方が２回利用した場合には２件とか、おおむねそのような形で表記をしておりますけれども、その辺また改めてしっかりと精査をしてまいりたいと考えております。","voiceIndex":294,"id":"exchange-121"},{"speaker":"須藤委員","kind":"質問","question":"今度、特定健康診査というのが２万５,７００件になっていますね。そうすると、どちらかで同じように合わせていかなければ、健診についても、件にするなら件。ただ、顔を並べてこうだという話じゃなくて、次に検証する仕組みづくりはどういうふうにできているんですかという質問もあわせて。ただ、みんなで話し合っていますということでいいか、どうか、教えてください。","respondent":"山田副区長","answer":"ご指摘いただいたとおり、特定健診が有効に働くためには、それぞれの実態をきちんと把握して、トータルの効果を上げていかなければなりませんので、４月以降、新しく今行っておりますプロジェクトの形を確立するような形で進めさせていただきたいと思います。","voiceIndex":297,"id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"私は１９５ページ、高齢福祉費の中で、見守りネットワーク、そして、１９７ページ障害者福祉費の緊急一時保護という話をします。緊急という言葉が使われていますが、緊急ということならば、昼夜深夜を問わず、品川区では対処できるような部署はあるんでしょうか。それをまずちょっとお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長、高橋障害者福祉課長","answer":"２４時間、緊急対応の体制ですけれども、基本的に、第一義的には、高齢福祉課のほうで対応しています。緊急一時保護のことですが、短期入所とか、緊急一時保護ということで、施設のほうで対応できる場合については、施設のほうでは２４時間対応しています。","voiceIndex":300,"id":"exchange-123"},{"speaker":"須貝委員","kind":"確認","question":"将来的には、水道メーターでも確認できるような、今、実験が進められております。そして、今回、品川区の中で、孤立死ということが出ております。全額じゃなくてもいいですから、支援をして、その方がちゃんとお元気なようだということを監視できるような仕組みづくり、システムづくりを、私はすべきだと思うんですが、その辺について、ご見解をお聞かせください。","respondent":"蓼沼高齢福祉課長","answer":"そういう機器類の使用も含めて、効率的なネットワークが形成できないか検討してまいりたいと考えております。","voiceIndex":303,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問・要望","question":"それについて、警察の方とちょっと相談願いまして、緊急でその方の命を救助に行く、守るために行くわけですから、そういうときは、駐車禁止はしないように、行政のほうから警察のほうに働きかけるということも、私は大切じゃないかなと思うんです。ヘルパーなんかは、ほかの地域では、やっぱりそういう要望があることを聞いておりますが、ご見解をお聞かせください。","respondent":"蓼沼高齢福祉課長","answer":"私どもで、実際にそういうようなケースで対応しているのは、タクシーを使ったり、あるいは、自転車を使ったりということでございまして、場合によっては警察に連絡して、立会いのもとということがありますので、ただいまのご指摘は、あまりちょっと例はないかなと考えております。","voiceIndex":305,"id":"exchange-125"},{"speaker":"堺委員","kind":"確認","question":"私のほうから、２１３ページの保育園運営費に関連して何点かお伺いをします。それから、２１９ページの親育ち支援事業についても、何点か確認をしたいと思います。あるいは、資格の有無というんでしょうか、この辺はどうなっているんでしょうか。その辺、今、現況がどうなっているのか、教えていただけますか。","respondent":"小林保育課長","answer":"園長の資格要件として、法定で、今こういった資格でなければ園長になれないという規定はございません。ただ、今後、動向としては、法定化の動きがあるやに聞いております。","voiceIndex":308,"id":"exchange-126"},{"speaker":"堺委員","kind":"質問","question":"わかりました。現在はないということですが、実は、１月１２日に、厚生労働省が、幼稚園の園長については、何か教育に関する職に１０年以上あったこと、こういった要件を定めて資格化されていると。まだ決まったわけではありません。あるいは、こういう流れについて、どういうふうなお考えを、保育課長はお持ちでしょうか。ちょっと教えていただけますか。","respondent":"小林保育課長","answer":"私どもも、新聞報道等を含めた情報の範疇ですけれども、厚生労働省は、今後の子育て支援の充実を目指して、その拠点となる保育園長の資格化を目指したいということで、実施年次については。","voiceIndex":310,"id":"exchange-127"},{"speaker":"堺委員","kind":"質問","question":"わかりました。品川区的には、今、課長がおっしゃっておられましたが、豊かな経験の実務があるという人がその任についているということですから、品川区が進める保育事業についても、円滑に進んでいるだろうなと考えています。","respondent":"小林保育課長","answer":"そうした社会背景を十分に理解した上で対応できる人材としての園長の位置づけが、今後のポイントとなってまいるかと思います。品川区も、持てる人材を十分に活用しながら、こういった要請にこたえていけるように対応してまいりたいと考えております。","voiceIndex":312,"id":"exchange-128"},{"speaker":"堺委員","kind":"確認","question":"２点目は、きょうも何回か出ておりましたが、改めて、待機児童の解消について、ちょっと確認をしておきたいと思うんです。それをカバーするというんでしょうか、そういうことから、今回、学習研究社がそちら方面で認定こども園を設立をするということになってくると、ある一定のカバーはできてくるかなと理解をするんですが、そういう理解でいいんでしょうか。ちょっと確認させてください。","respondent":"小林保育課長","answer":"特に現在、若干、状況が厳しくなっております大崎、五反田の地域につきましては、もちろん需要対応を想定しておりました施設計画の既存の中で、学習研究社等の施設の開始を待つところではありますが、新年度に入りまして、その状況に応じては。","voiceIndex":314,"id":"exchange-129"},{"speaker":"堺委員","kind":"質問・要望","question":"こういう全体的な流れとしては、来るようです。ですから、国を挙げて待機児童解消についても、積極的に取り組みが、また新たな視点から取り組まれてくるですから、それに即応する、対応するような形で、区としても、今、お話がありましたような形で、全面的に待機児童解消策に取り組んでいただきたいと思うんですが、それについてのお考えを、もう１回お聞かせいただけますか。","respondent":"小林保育課長","answer":"私どもも、年次計画、目標として定めまして、今まで持っている施設サービスに加えて、在宅で子育てなさっている方への対応も含めて、可能な限り早期に待機児の圧縮が可能になるように努力してまいりたいと思います。","voiceIndex":316,"id":"exchange-130"},{"speaker":"堺委員","kind":"質問","question":"どうか、ひとつよろしくお願いいたします。そのときに、もう１点、ちょっと、昨年の決算特別委員会のときに、バラ措置についてちょっとお尋ねをさせていただいた。この４月に定期入園に関連して、このバラ措置は解消されているのか、その現況、ちょっと今の時点で教えていただけますか。","respondent":"小林保育課長","answer":"他方、３月当初、バラ措置になっている４８世帯につきまして、全件ご通知を申し上げまして、どちらかにこだわりを持たれますとなかなか対応ができないんですが、兄か弟かどちらか、どちらでもまとまるんだったらそういうことでいいですかという意思確認をしました。","voiceIndex":318,"id":"exchange-131"},{"speaker":"林委員","kind":"質問","question":"二つ、お聞きしていきます。１点は、１８７ページのホームレス対策事業という項目で出ているんですけれども、私どもの大沢委員から質問があって、品川寮はつくっていくということで、それはわかりました。東京都が実施していた、いわゆる山谷対策という形での施策が、２３区と合同にどうだこうだという東京都の勝手な言い方が聞こえてきます。品川区に指針はどこにあるんですか。","respondent":"志村生活福祉課長、冨岡高齢事業課長","answer":"お尋ねの、現在、私どもで行っているホームレス事業と山谷事業、これは全く別ですので、この中には全く入ってございません。それにつきましては、やはり運営主体は広域連合であると、さらに医療費というのは、どう考えても、これからは伸びる可能性があるという部分がありますので、広域連合の動向を見ながら、区としては。","voiceIndex":322,"id":"exchange-132"},{"speaker":"林委員","kind":"質問","question":"きのうからの続きで、長期計画も、実施計画もなくこれを進めていくというのは、だれがリーダーとしてやっていくんですか。だけれども、４８５ページには、福祉高齢事業部の職員１５人分の給与が載ってきているんですよ。１５人、職員が事業にかかわるといったら、れっきとした品川区の事業ですよ。どうしても、そういうふうに思えるんですけれども、きちんと説明ができる人、説明してください。","respondent":"福田企画部長","answer":"だからといって、行政計画が効力を失うわけではない。したがいまして、第三次長期基本計画も、それから、そのもとにあります総合実施計画も、平成２０年度については効力を持ったまま生きている。したがいまして、その大方針の中でそれぞれの事業が運営されていく。","voiceIndex":325,"id":"exchange-133"},{"speaker":"林委員","kind":"意見","question":"理屈ではわかるんだけれども、行政というのはそういうものじゃない。じゃあ、後期高齢者医療特別会計の約６０億円ぐらいの予算、ここに国民健康保険が広域連合に出す３９億円というお金もあるわけですよ。そうすると、品川区のお金が、後期高齢者医療制度にどのぐらい使われていくのかというのは答えられますか。","respondent":"木下福祉高齢事業部長","answer":"したがって、我々としては、法律にのっとった仕事を基本的に進めていくということであります。","voiceIndex":327,"id":"exchange-134"},{"speaker":"林委員","kind":"質問","question":"それは最初に、僕のほうが申し上げた。広域連合という事業主体があって、品川区がやることは、限られている事業だけやっていくんだと。だけれども、１５人の品川区の職員が携わってやる事業もあるんですよね。それは事実でしょ、ここに書いてあるんだから、予算に出てきているんだから、だったら僕は、今の体制でできるんですかと。担当課長もつくった介護保険と似てくる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-135"},{"speaker":"土井委員","kind":"質問","question":"私からは、１８７ページの、先ほどもありましたが地域密着型サービス施設整備助成事業に関連をして、介護保険制度等にも同じようなサービスという名前がついておりますので、それらとの関連でお伺いをすること。それからもう一つは、１９１ページの高齢者社会参加プログラムについて、お伺いをする。それからもう一つが、１９５ページの火災警報器について、お伺いをすること。","respondent":"蓼沼高齢福祉課長","answer":"グループホーム２ユニットにつきましては、東京都におきましてはグループホームの整備がおくれているということで、緊急整備ということが求められておりまして、そういう意味で言えば、枠を確保して、民間事業所の事業の参入について、そういう対応を図っているというものです。","voiceIndex":331,"id":"exchange-136"},{"speaker":"土井委員","kind":"質問","question":"そこら辺を含めて、ちょっとお考え聞きたいということが１点です。４８７ページの、後期高齢者医療の話なんですが、今決まって、今年から実施をしていくという話なのに、これだけが妙に具体的に大江戸温泉物語と書いてあるんですけれども、何でこれだけが妙に具体的に出てきているのか、お伺いしたいと思います。７５歳以上の人は大江戸温泉物語大好きなのかなというふうに思うので、何だろうということです。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"火災警報器についてのお尋ねですけれども、これにつきましては、メンテナンスということは予定しておりません。大江戸温泉物語の利用料金の部分ですが、今まで、平成１６年度から国民健康保険で実施しているもの、これが７５歳以上の方がこちらになったからといっても、利用できないということじゃ困りますので、組ませていただいたです。","voiceIndex":333,"id":"exchange-137"},{"speaker":"土井委員","kind":"質問","question":"火災警報器の件なんですけれども、１０年ですか。３年ぐらいで云々という機器もいろいろありますよね。これは１０年ものを勧めているということですか、わかりました。それはただ思っただけで結構です。多機能ということですから、高齢者に係わる皆さんのものと、子どもに係わるものがあったり、障害者に係わるものがあったり、いろいろ考えられるんじゃないかと思うわけです。どうでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"法律上のそういう位置づけがありますので、なかなか、委員のご指摘のあった点は難しい面がありますけれども、今、ご指摘のありました富山方式も含めて、今後、何か可能なものがあるかないか等を検討してまいりたいと考えております。","voiceIndex":336,"id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問","question":"障害者自立支援法の中には、障害者がもっと働ける社会に、それから働く意欲のある方に必要な訓練を行う就労支援、また、企業などと連携をし、障害者の働く場を広げると、こういうふうに書いてあるんですけれども、障害者自立支援法が始まって、就労の支援がどのように進んでいるのか、お伺いします。","respondent":"高橋障害者福祉課長","answer":"就労支援センター、げんき品川のお尋ねですが、これにつきましては、ハローワーク、それから就労のための機関と連携しながら、知的障害者の就労に向けた講座を、年２回程度進めているところです。","voiceIndex":339,"id":"exchange-139"},{"speaker":"飯沼委員","kind":"質問","question":"一番最初の障害者自立支援法が始まって、どのように就労支援が進んでいるのか、大きなところをちょっと伺ったので、それを一つ。それから、一般就労につながっているところで、長かったり、短かったりいろいろしているみたいなんですが、長くてどのぐらい継続しているのか、わかったら教えてください。","respondent":"高橋障害者福祉課長","answer":"障害者自立支援法ができまして、それぞれのところで、具体的に自立訓練を受けた中で就労のＡ型、就労のＢ型等を継続的に進めるというようなところ、また福祉的なそういう職場ではなく、一般就労に向けたところを、それぞれ訓練を受けながら行っているものです。","voiceIndex":341,"id":"exchange-140"},{"speaker":"飯沼委員","kind":"質問・要望","question":"長くてどのぐらいの就労になっているのか、後で教えてください。基盤整備に十分に取り組んでいくことが、今は求められていると思うんですが、この点。それからもう１点は、ハローワークや企業、そして、区がネットワークをつくって、企業に対する働きかけを広げていく、区がコーディネーターの役割を十分に果たすことが、今、求められていると思うんですが、３点、お答えをいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"長期間働いている人はどのぐらいかですが、平成１６年にできたときから、ずっと現在も継続してる方がおります。ですので、何年というところは、ちょっと計算していただければと思います。","voiceIndex":343,"id":"exchange-141"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区がみずから障害者の方々の仕事をつくってほしい。これは、品川区の中に雇用の場所をつくってほしいということなんです。前に伺ったら、品川区は障害者雇用の率が３.３３％で、２.１％を上回っているということなんですが、この中身においては、知的障害の方とか、精神障害の方は含まれていないようなので、ぜひ、そういった差がなくというか、どんな障害の方も品川区で受け入れてほしい。","respondent":"木下福祉高齢事業部長","answer":"どういうところから、まず考えるかということになってくるわけでありますけれども、今、ご指摘の部分も、区の職員の場合については、一定の統一選考のような制度もありますから、その問題はありますけれども、まずどこから手をつけるかという点でお話をしますと、今。","voiceIndex":345,"id":"exchange-142"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、一般就労につながるような努力を続けて、ぜひ成果を生んでいただきたいと思います。それから、すぐできないところでも、いろいろな仕事は探せると思うんです。そういう方の場をぜひつくってほしいんですが、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"実際、長時間労働というのが一般就労ですので、短時間労働でも可能な職場とか、いろいろな職場制限がありますので、その辺については、ご本人の状況を踏まえた上で紹介し、サポートをしていくということできめ細かくやっていきたいと思いますので、よろしくお願いします。","voiceIndex":347,"id":"exchange-143"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひぜひ、きょうの質問は、区がみずから足を前に出すというか、力強く踏み出していただきたいので、よろしくお願いいたします。次に配食サービスのほうにいきます。５３７ページに、配食サービス栄養改善事業とあるんですが、これは以前の配食サービスとの違いがあるのか、どうか。この対象の人数と、１食幾らで、何回受けられるのか、そこのところを教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"５３７ページに計上しておりますのは、昨年度までは、５３５ページの介護予防事業費のデイサービスセンター等活用型介護予防事業の中で実施をしていたものでございまして、これを、制度の性格上、任意事業のほうが適しているということで、こちらに組みかえたものです。","voiceIndex":349,"id":"exchange-144"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６００円で週２回までということで、ぜひ、回数を増やしていただきたいのと、６００円がちょっと高いので、地域センターでやっている食事サービスと同じぐらいまでの値段に下げていただきたいと思っています。食べることは、ほんとうに楽しみであるし、大切なことなので、必要な人に毎日行ってほしいなと思っているんです、よろしくお願いします。","respondent":"蓼沼高齢福祉課長","answer":"この値段について、学校の配食サービスよりも高いという現状がありますが、これについては、地域食事サービスのほうについても、いろいろ総合的に検討がされているようですので、そちらのほうと勘案して、総合的に検討を重ねてまいりたいと考えております。","voiceIndex":351,"id":"exchange-145"},{"speaker":"飯沼委員","kind":"質問・要望","question":"栄養不良と孤独に対する発見のおくれというところで、８０歳以上の急死の場合、太っている人よりもやせていて、食事が食べられない状況で急死をされるというのが多くて、こういった面では、ほんとうにぜひ、人の命を守るというところで、この回数を増やしていただきたいんですが、命を守るという立場で、暖かい見守りのために必要だと思います。いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"適切に検討してまいります。","voiceIndex":353,"id":"exchange-146"},{"speaker":"三上委員","kind":"質問・要望","question":"私は、１９５ページ、家具転倒防止対策助成、それから、１９３ページ、ひとり暮らし高齢者等福祉費、高齢者世帯の安否確認事業等についての件、それから、２１９ページ、子育て支援センター内での、トワイライトステイ事業について、関係することでお伺いしたいと思います。それから、ひとり暮らしの安否確認についてですけれども、先ほど、質問がありましたので、これは簡単に伺います。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長、諸岡児童課長","answer":"それからシルバー人材センターのほうに依頼をするという流れで、シルバー人材センターのほうからお宅に出向いて、中をゆっくり見させていただいて。例えば、新年度に検討を進める考え方の中にも示されておりますけれども、例えば、ごみの各戸収集ですとか、あるいは新聞配達、または。家庭あんしんセンターにおけますトワイライトステイ事業についてですけれども、この事業は。","voiceIndex":356,"id":"exchange-147"},{"speaker":"三上委員","kind":"提案","question":"」ということで、その当時北海道大学にいらっしゃいまして、今は、名古屋工業大学の、多分教授をされているんじゃないかと思いますが、その方がご自分でつくられたソフトを開放されて、要するに部屋の中の家具をどう置いたらいいのかということを、自分でも判定できますという、そういうソフトを使ったらどうですかということを提案してきているわけです。こういうふうにも言っていらっしゃる。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長、諸岡児童課長","answer":"基本的には、高齢者のお宅にお伺いして、いろいろな器具をお示しして、どういうものをつけましょうかというところでつけていくのが、今。今、委員ご指摘のように、インターネットによる遠隔モニターの操作、あるいは、先ほど来出ておりました、ガス、水道の機器類を使ったものも含めまして。そこで、トワイライトステイ事業におきましても、この間、皆さんに公平に利用いただくためにキャンセル待ちの制度を設けるとか。","voiceIndex":360,"id":"exchange-148"},{"speaker":"三上委員","kind":"質問","question":"ずっとやっていた事業を、品川区はやめてしまった。結局、それを今、国がまたさらにこれをやろうしているわけです、事業拡大する。そうならば、これは早くそういう事業に取り組むということも一つの方法ですし、先ほど、いみじくも言っていただいた、富山方式というのがあるとするならば、いろいろな方式を使ってでも、そういったことができるんじゃないかと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":364,"id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"認証保育の話は、もうたくさん出ているので、教えていただきたいのは、申込み者数が１,４００人ぐらいあった。ここら辺のところは、基本的には、高齢者に対しての対策をしているわけですから、あえてここで聞きますけれども、例えば、学校の配食サービスを受けている方は昼で２９０円、夜で４００円ということもあるけれども、これは６００円。そこら辺の考え方を教えていただきたい。","respondent":"小林保育課長、冨岡高齢事業課長、中山地域活動課長","answer":"ただ、総数から推定いたしますと、今年度、４月、５月の段階で、０歳、１歳の階層については、認証保育所に入れない方も、場合によって。このままこういう住宅が、介護の担えるような部分になるかということを考えまして、総合的に、居住系の施設の検討をさせていただきたいです。ボランティアの有効活用と、区内のマンパワーの有効活用というものを、幅広い視野の中で、高齢福祉課とも連携をとりながらやっていきたいと思っています。","voiceIndex":366,"id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"提案","question":"そのかわりいろいろありますよ。一つ心配は、品川区はどう思っているかわからないんですけれども、Ｄ２１階層の人が、もし認証保育にいっちゃうと、歳入が減っちゃうから問題かなと、ちょっと思っているかなと、そういうことはないと思うんですけれども、そういうことを考えるのであれば、私は、こういうときこそ、こういう手を打っていくべきだろうと思っていますので、そこら辺の見解を教えていただきたい。","respondent":"小林保育課長、蓼沼高齢福祉課長、諸岡児童課長","answer":"は委員、ご指摘のとおり、認証保育所の質的な向上が図られてまいりますと、よりライフスタイルに応じた選択が行われるものと考えております。ですから、この制度を使って、例えば、フロアを分けて、２階だけに特定をかけるような手法もありますので、そういった手法を含めて。今後、ご指摘のように、人口推計等も含めて、総合的な予算算定の方法等も十分に勘案していきたいと思っています。","voiceIndex":370,"id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=898#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":124969,"voices":374}},{"id":"h20-20080310-3","meetingId":"h20-c-budget","date":"2008年3月10日","dateIso":"2008-03-10","committee":"予算特別委員会","time":"午前１０時０３分～午後５時５２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年度品川区一般会計予算","agenda":"平成２０年度品川区一般会計予算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"私のほうは２３７ページ、食からの子育て支援事業、食事改善推進生活指導、２５５ページの観光アクションプラン、この点について伺いたいと思います。これを受けて、この２事業も含めて、品川区での事業での変化は、こういった国や都の背景からあったのか、その点をまず伺いということ、そしてあと国は推進計画作成を各市町村でも平成２２年までに５０％以上という目標を掲げています。","respondent":"川口品川区保健センター保健サービス課長","answer":"本区におきましても、ただいまご説明いたしましたように、庁内で食に関する議論を今現在展開されてあります。その展開の経緯を踏まえて、我々のほうもさらに検討を進めてまいりたいと考えています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"次に行かせていただきます。そういう流れから、都の計画事例から品川区を照らして何点か伺いたいと思います。そういった中では自慢の食文化だと思うので、これが継承されていく、あるいは担い手の人材育成などはだれかが応援していかなければいけないと思いますが、そういった意味では、家庭や個人ではなく、行政の取り組みの１つかなと思いますので、この点についてご見解を伺いたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"２点目ですけれども、行政として、個人だけではなくて、地域としての取り組みということのご質問だと思いますけれども、区としましては、ただいま食事バランスガイド等の普及等がありますので、それをまず第１としまして、地域でいろいろなお店屋さん等の協力をもとに。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"どうしても観光という点は、とらえ方も広いですし、全国的に見ても、国や都がメンツをかけて取り組んでも長年かかるといったものではあるんですが、かかわる方、あるいは住んでいる方にもいい面、そして来訪者に対してもてなすというまさしく今回のテーマどおり、非常に大きな時間も労力もかかるとは思いますが、それを当然と考えていらっしゃって、これからも随時継続的に推進をしていかれるのかどうか。","respondent":"金子産業振興課長","answer":"どうしても旧東海道、品川地区のほうに観光資源が偏在しているわけですけれども、荏原地区においても、特に商店街という非常に大きな観光資源があると考えていますので、区全般に関しまして、さまざまな団体と連携しながら。","voiceIndex":8,"id":"exchange-003"},{"speaker":"金野委員","kind":"確認","question":"私のほうからは、２２９ページの予防接種費についてお伺いします。いきいきあんしん子育てガイドの中にも、予防接種に関することを詳しく載せてくださって、本当にこれはお母様方、乳幼児の予防接種に関しても非常に見やすいなというところでありますけれども、まずこの定期予防接種に関して、協力医療機関で行うものと集団接種であるものがあると思いますが、確認のため、それぞれの内容をお聞かせください。","respondent":"倉橋品川区保健所保健サービス課長","answer":"その中でも現在、ＢＣＧというものを乳児健診のときに実施しているということで、集団接種方式が原則となっております。それからポリオは病気の性質上、一度にその地全体の予防接種をしたほうがいいということになっておりますので、これも集団接種となっております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"金野委員","kind":"質問","question":"その下のところにあります臨時職員賃金というところで、個別接種は協力医療機関でしますので個別だと思うんですが、イメージ的には、多分この集団接種のところで配置をされる方なのかなとイメージしているんですが、平成１９年度の予算でいきますと７９万３,０００円、この予算書でいきますと４３３万９,０００円と、平成１９年度と比べますと、実に５.４倍になって計上されているんですが。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これは一連の流れの中で実施しまして、その中でＢＣＧを接種するということになっておりますので、一連の流れの中で対応し、子どもの状況を見ながら対応しながら予防接種をしているという実施の方法となっております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"金野委員","kind":"確認","question":"そうしますと、ＢＣＧはこの法改正によって集団接種になって、全体でお子さんを連れてくるお母さんたちに対応しながらするということで、人員が大幅にアップという解釈でよろしいでしょうか。確認のため。そうすると、ポリオに関しては、集団接種ですので、保健所また保健センター、地域センターを活用して集団でやっていますよね。ＢＣＧの場合は、どのようなところでやっているんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"説明が不十分で申しわけございませんでした。ポリオにつきましては、今、委員ご指摘のとおり、春、秋に臨時に保健所をはじめといたしまして、居住地の近くということで、あちこちの文化センターなどの会場を借りまして、集中的に実施しています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"そうすると、結核の定期予防に関することで増額、たしかＢＣＧは、私も子どもがまだ５歳ですから、５年前に受けたときに、健診時のときにたしかしたなという記憶があったので、ＢＣＧは集団になっていたはずで、その人員の大幅なアップのためにこの臨時職員というのがどうも結びつかないんですけれども、その辺、もう１回だけ説明をお願いできますか。","respondent":"太田健康課長","answer":"私のほうからご答弁します。ＢＣＧについては、昨年までは、予算書、説明書でいきますと２２９ページ、定期結核健康診断の中に当初予算で組み込まれておりました。","voiceIndex":17,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"その地域の、例えば五反田文化センター、南大井文化センター、それぞれ１日しかないために、その地域の方たちが、ほかの日でもいいですよということなんですけれども、例えば６月に行われる梅雨の時期などは、雨などで子どもを連れていくのが大変で、もし地域センターでもう１日ぐらいずつ増やすことができるならばという声もありまして、時期がずれても予防接種は大丈夫ですよという声は聞くんですけれども。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ご要望の趣旨は大変よく承りました。ただ実際にそれを配分するとなりますと、会場の都合、それから、各地域がそこに行けるように、重なって配置する等の技術的な問題もありますので、これは可能なところは十分に検討して実施するような形で検討していきたいと考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひご検討をよろしくお願いします。任意接種のほうで、平成１９年度の４月１日から施行されておりましたおたふくと水ぼうそうの予防接種に関しての一部助成が行われているということでありますので、これは本当に助かります。お母さんたちも助かりますので、ぜひこういったことも含めて、また機会がありましたら要望しますが、これは感謝の思いの言葉で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは２５６ページの中小企業対策費に関連いたしまして、原油価格、原材料費、穀物価格の高騰から、ぜひ区内中小零細企業の営業と暮らしを守るために、実態調査、緊急対策の実施を求めまして質問したいと思います。原油価格の高騰が暮らしを襲っています。伺いたいのは、原油価格、材料費、穀物価格の高騰による区内商店、中小零細企業の影響について、どのような調査を行っているのかお聞かせください。","respondent":"金子産業振興課長","answer":"さらに経営相談につきましても、最近の経営相談の傾向としましては、いわゆる不況関連の融資の相談から、セーフティーネットの不況業種関係の認定というのが非常に増えているというところで、私どもとしましても、特に融資あっ旋に関しまして、この認定の処理について。","voiceIndex":23,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は価格高騰に伴う区内の調査を行っているのかということを伺いました。景気動向については３カ月に一遍というお話がありましたけれども、ちょっとお聞かせください。夫婦２人でプラスチック成型をやっている方のお話を伺いました。こうした実態をきちんと調査の中でつかんでいただきたい。改めて原油、材料、穀物価格の高騰による実態調査をしっかりと行うべきだと思うんですけれども、いかがでしょうか。","respondent":"金子産業振興課長","answer":"そういう意味で、私どもの融資あっ旋関係につきましては、金融機関とどうしても調整していく、協議していくという作業があるわけですけれども、これについてもできるだけ協定金利を低くして対応しているとともに、また先ほど企画財政課長がご説明申し上げましたとおり。","voiceIndex":25,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はこの従来の景気動向調査に加えて、この価格高騰に伴う実態をしっかりつかんでいただきたい、この深刻さを把握していただきたいと述べているんです。伺いたいのは、私はこの末端の弱いものに価格高騰のしわ寄せをさせるのは間違いだと思うんですけれども、いかがでしょうか。区としてできる暮らしと営業を守る新たなあらゆる対策を検討すべきときではないかと思うんですけれども、いかがでしょうか。","respondent":"金子産業振興課長","answer":"委員ご指摘の末端のところにしわ寄せがというお話ですけれども、経済構造そのものが非常に複雑なメカニズムで起きていますから、そういう意味ではなかなかどれ１つが原因というのを追及して、また予測するのは非常に難しいと思いますが、私どもとしましては、融資あっ旋のほか。","voiceIndex":27,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"私は４つのクリーニング屋さんにお話を伺ってきました。クリーニング店はありとあらゆるものが石油製品ですから、もろにその影響を受けています。私は、渋谷区を参考に緊急支援策を、ぜひこの品川区でもこういう視点に立った対策を実施すべきではないかと思うんですけれども、いかがでしょうか。","respondent":"金子産業振興課長","answer":"それを原料とした製造業種についても影響が出ております。そういう意味では、私どもとしては、今後とも状況を注視しながら、できる対応をしていきたいと考えています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"稲川委員","kind":"質問","question":"私は２４７ページのみどりの街なみ整備事業全般をお伺いをいたします。改めてお伺いするわけですが、この事業の目的と概要を教えてください。そしてあとこの事業自体が品川区の独自というんでしょうか、そういう事業なのか、それとも国と都などと連携した事業なのか教えてください。","respondent":"藤田道路公園課長","answer":"みどりの街なみ整備ということで、全般のお話だと思いますけれども、私どもは緑の施策は、現在の長期基本計画あるいは市街地整備基本構想にも基づき進められておりまして、そういったものの中で緑豊かな街なみをつくっていこうということで、大きな目標を掲げ。","voiceIndex":32,"id":"exchange-014"},{"speaker":"稲川委員","kind":"質問・要望","question":"上から３行目になるんですが、緑豊かな街なみづくり助成と書いてあるんですが、実際この助成というのはどこに助成しているのか。企業なのか、民間なのかで、今年度もし実績があれば教えていただきたい。ホームページを見ても、屋上緑化に上限３０万円という形で助成があるとは書いてあるんですが、この壁面緑化というのは助成とか何も書いていないんですが、どういう意味なのか教えてください。","respondent":"藤田道路公園課長","answer":"こういった事業に当てはまる事業については助成の対象になりませんので、３００m2以上が緑化指導の対象になりますので、それ以下の小さなお宅の方が助成を受けて行っているような形というのが実際には多いかなということで考えております。","voiceIndex":34,"id":"exchange-015"},{"speaker":"稲川委員","kind":"質問・要望","question":"できればわかりやすく書いていただければと思いまして、申しわけないです。その下にもあるんですが、緑化啓発・普及事業と書いてあるんですが、実際具体的にどういった形でどこをターゲットに普及活動をしているかを教えてください。普及活動をしている、多分平成１９年度もそうだったと思うんですが、実際、成果というか、どれだけ普及しているのか、その辺のデータがあったら教えていただきたい。","respondent":"藤田道路公園課長","answer":"こういった事業の中では、園芸教室だとか、そういった教室等も行いながら、多くの方にご利用いただき、緑化の普及に努めているところです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"稲川委員","kind":"質問","question":"これをずっと事業で進めていく、事業であるから達成とかという言葉が出てくるとは思うんですが、達成率、どこまでいけばそれが達成されるのか。屋上緑化をやってもなかなか根が張らないという話もあるんですが、実際この品川区内で、民間のビルなり、企業なり、どれぐらい達成しているのか、緑被率というんですか、その辺を教えてください。","respondent":"藤田道路公園課長","answer":"そういったものを絡めながら、品川区の目標というのをまた新たに、１つ目標をクリアしておりますので、次の目標をまた考えていきたいと考えています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"最後に、例えばこの緑を増やすことによって、私も素人ながら考えると、今、ヒートアイランド現象とかさまざまなことが言われておりますが、緑を増やすことによって、品川区もすぐそこは大井ふ頭があるような状況の中で、実際、緑を増やしたことによって温度が変わるとか、涼しくなったとか、そういったデータというのはあるんですか。","respondent":"藤田道路公園課長","answer":"そういった形でさまざまな形での緑化を進めることが、大きな意味でのヒートアイランド対策等に寄与しているものと考えています。","voiceIndex":40,"id":"exchange-018"},{"speaker":"山内委員","kind":"質問・要望","question":"私は２５３ページの廃棄物作業費について、全般的にお尋ねさせていただきたいと思います。改めて再確認をさせていただきまして、この品川区の一般廃棄物処理基本計画というのの中に事業系ごみのことが書いてありまして、事業者はみずから処理施設へ廃棄物を持ち込むか、もしくは許可業者へ委託をして処理をするのが原則であるとうたっております。その辺の説明をお願いしたいと思うんです。","respondent":"秋山資源循環推進課長","answer":"したがいまして、事業系のシールを張った、１０ｌ当たり５４円の現行料金、１kg２８円５０銭をいただいているのは一たん区に入りまして、処理処分の分は清掃一部事務組合の分担金として区から清掃一部事務組合のほうに支払っているという状況です。","voiceIndex":44,"id":"exchange-019"},{"speaker":"山内委員","kind":"確認","question":"事業概要を見ました。手数料のところを見ますと、これは確認になっちゃうのかもしれませんが、家庭廃棄物は２８円５０銭と書いてあり、事業系のごみも２８円５０銭と書いてある。わかります、おっしゃっているのは。だけど、事業系のごみに対しては、シールを張って、これは確認なんですけれども、そのシールを張った時点で、事業者は手数料を払ったということになるんですか。事業者が区に対して。","respondent":"秋山資源循環推進課長","answer":"シールを張った時点で、収集運搬分と処理処分分を区に支払ったということになります。","voiceIndex":46,"id":"exchange-020"},{"speaker":"山内委員","kind":"質問","question":"区に支払ったわけですね。そのシールの１０ｌごとの５０円の中から、区は２８円５０銭を清掃工場に払っているということなんでしょうか。","respondent":"秋山資源循環推進課長","answer":"１２円５０銭分が処理処分分ですから、清掃工場で支払われる。区が収集したごみの１年間のトータルの量を各区のごみ量に案分して、かかった費用をごみ量で案分して、清掃一部事務組合のほうに分担金という形でお支払いをしているということです。","voiceIndex":48,"id":"exchange-021"},{"speaker":"山内委員","kind":"質問","question":"２５１ページに二十三区清掃一部事務組合分担金を１７億円近く払っている。この分担金というのがよくわからないんですね。この分担金というのは、どういう形で払われているのかというのをちょっと教えてください。","respondent":"秋山資源循環推進課長","answer":"分担金ですけれども、清掃一部事務組合の使う清掃工場を建てる費用ですとか運営費、過去に建てた工場の公債費、組合債の償還費というものを、すべて清掃一部事務組合の歳出を２３区が負担をするということで。","voiceIndex":50,"id":"exchange-022"},{"speaker":"山内委員","kind":"意見","question":"案分の案分率とかというのは、例えば人口とかそういうのがありますよね。ごみの量とかが各地区によって違ってきますよね。そういう数字の出し方というのはどういう。","respondent":"秋山資源循環推進課長","answer":"各区が毎日収集で集めているごみ量がありますので、それを集計した年間に持ち込んだ量がありますので、そのごみ量で案分をするです。","voiceIndex":52,"id":"exchange-023"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、今、品川区の支払っている分担金は、ごみ量に対しての案分ということで、例えば２３区の中では、払っている数字的なものというのは、大体どれくらいの順位というか、そういうところなんでしょうか。","respondent":"秋山資源循環推進課長","answer":"現在、区収の部分は全体の３.８２％ですので、案分するときの３.８２％が品川区の分ということになってあります。","voiceIndex":54,"id":"exchange-024"},{"speaker":"山元委員","kind":"質問・要望","question":"私は２４１ページの公害健康被害補償事業費のところをお伺いさせていただきたいと思います。初めに、この公害健康被害補償事業費というのはどういうものなのかを教えていただきたいと思います。","respondent":"太田健康課長","answer":"２つ目は、東京都で１８歳未満のお子さんを対象とした大気汚染の健康被害にかかる都独自の医療費の自己負担分の助成と、こういう２つの制度があります。","voiceIndex":57,"id":"exchange-025"},{"speaker":"山元委員","kind":"質問・要望","question":"品川区内に何人かいらっしゃると思うんですけれども、年齢的に、また何人ぐらいいらっしゃるのか、また先ほどの東京都から指定された子どもたちの人数も、また年齢も、おわかりになれば教えていただきたいと思います。","respondent":"太田健康課長","answer":"内訳ですけれども、０歳から９歳までで１２６名、１０歳から１４歳までで４０９名、１５歳から１８歳未満で１２０名ということになってあります。","voiceIndex":59,"id":"exchange-026"},{"speaker":"山元委員","kind":"質問","question":"先ほどご説明いただいたときに、この項目の中に大気汚染障害者認定審査事務補助員経費というお話がありましたけれども、この補助員経費というのはどういうものなのか、ご説明いただけますでしょうか。","respondent":"太田健康課長","answer":"これが８月１日から施行することになってあります。それで５、６、７の３カ月間、事前申請受付、要するに８月１日から医療費が自己負担なしで受けられるようにということで、円滑にできるようにという形で３カ月間、事前申請受付を行います。","voiceIndex":61,"id":"exchange-027"},{"speaker":"山元委員","kind":"質問","question":"今のお話でいきますと、認定を受けるのが、毎年それとも何年かに一遍とかということになるんでしょうか。","respondent":"太田健康課長","answer":"８月１日以降については、申請の受付、認定、それから医療証の発布まで、区が一括して実施をしていくということで、東京都のほうから事務委任を受ける予定です。これについては現在、都議会で条例を審査中と聞いてあります。","voiceIndex":63,"id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"しつこいようなんですけれども、その認定は医療費が無料になるかと思うんですが、それ以外の助成といいますか、特に９１６人の方は皆さん成人でいらっしゃいますので、生活がおありかなと思うんですが、そういう方たちに対しての生活の援助といいますか、そういうものに関してはあるんでしょうか。教えていただきたいと思います。","respondent":"太田健康課長","answer":"今のお話ですけれども、整理しますと、１つは、法律に基づくいわゆる公害健康被害の方に対する助成です。それについては医療費の補助と、生活給的な意味合いでの障害補償費というものが支給されてあります。","voiceIndex":65,"id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"次の福祉事業のところにリハビリテーションということが書いてあるんですけれども、このリハビリテーションというのはどういうことが行われるんでしょうか。","respondent":"太田健康課長","answer":"２点目は、リハビリですけれども、６５歳以上の高齢者の方のインフルエンザを実施していますけれども、呼吸器系ということで、６５歳以上の方のインフルエンザの予防接種、自己負担分の助成ということも実施しています。","voiceIndex":67,"id":"exchange-030"},{"speaker":"山元委員","kind":"質問","question":"その方々によって重さが違うかなと思うんですが、自分の足でいろいろなところに足を運べる方はいいと思うんですけれども、本当に苦しくて外に出られないような方もいらっしゃると思うんですが、そういう方に対してのリハビリといいますか、手だてといいましょうか、そういうのは区としては何かなさっていらっしゃるんでしょうか。","respondent":"太田健康課長","answer":"現在のところ家庭にいらっしゃる方に対するリハビリというのは、特に実施をしてございません。","voiceIndex":69,"id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"実は私の知っている人がやはりこの公害認定を受けまして、大変苦しんでいらっしゃいました。区から何の訪問もなくて亡くなってしまったんですが、ここに出てこれない方たちも大変苦しんでおりますので、そういう意味ではぜひ苦しんでいる方の気持ちになって、一つ一つ対処していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"２３５ページの一歳六カ月児健康診査、三歳児健康診査についてお伺いしたいと思います。この２つの健診の主眼と、どちらの機関でどのような健診をされるか、ご説明をお願いします。","respondent":"川口品川区保健センター保健サービス課長","answer":"したがいまして、１歳半および３歳は、ただいまの繰り返しになりますけれども、これからの発育、発達の一番重要な時期ですので、内科健診および歯科健診を行っているです。","voiceIndex":73,"id":"exchange-033"},{"speaker":"高橋委員","kind":"質問","question":"これは保健所、保健センターでやられているのでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"健診の実施の場所ですけれども、本区ではご存じのように保健所、保健センター、大井保健相談所の３カ所でそれぞれ実施しています。","voiceIndex":75,"id":"exchange-034"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、この後、子どもが小学校に上がるまでに健診はないのでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"さらに先ほどちょっと触れさせていただきましたけれども、心理判定とか発達健診、その中でそれの対象者がございましたら、これも月に１回、心理経過観察健診、それから発達健診を３所で行ってあります。","voiceIndex":77,"id":"exchange-035"},{"speaker":"高橋委員","kind":"質問","question":"１歳６カ月と３歳の健診で、発達障害だと思われる子どもは、今年度で結構ですけれども、どれぐらい把握されているでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"そういう意味でいけば、１歳半および３歳児健診、毎年対象は変わりますけれども、５％から数％の間で、機関健診の受診者の中で、それ以降の経過観察健診ということで受診していただいてあります。","voiceIndex":79,"id":"exchange-036"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、今、３歳児健診までの話をしたんですが、その後、小学校に入る前に就学前の健診があるんですが、その間、３年の間があいてしまうということがありまして、発達障害に関しては早期に発見して早期に支援することが大切だと言われているんですけれども、５歳などでそのような発達障害の兆候がよく見られると言われているんですけれども、５歳児に総合健診として。","respondent":"太田品川区保健センター大井保健相談所長","answer":"集団生活に入ったところで、幼稚園、保育園で気づかれることが多いので、そこで見つけた発達障害の子どもは、児童デイサービスでの相談および３所で行っております発達健診のほうで相談に乗っているです。","voiceIndex":81,"id":"exchange-037"},{"speaker":"高橋委員","kind":"質問","question":"品川区は障害を持った子に対するいろいろなサービスが多数用意されているので、相談とかその先に紹介をして、そこできちっと支援を受けてもらえればいいと思うんですが、保護者の方がどうしてもなかなか受容できないというところが大きな問題だと思うんですが、そのあたりについてはどのように説明して、この支援を受けたほうがいいということを説明されているんでしょうか。","respondent":"太田品川区保健センター大井保健相談所長","answer":"親への啓発活動ですが、それは集団の機関健診のほうでも行っておりますし、今後東京都のほうでも就学前の子どもに対する啓発のためのパンフレット等をつくるということですので、それを配るという方向でやっていけるかと考えています。","voiceIndex":83,"id":"exchange-038"},{"speaker":"高橋委員","kind":"質問・要望","question":"しかし、この前のご説明のあった児童学園などは、登録が２０名というお話だったと思うんですね。先ほどの１歳６カ月と３歳児健診は母子保健法であり、障害に関するほうでは障害のほうで、就学前教育は学校教育法でということで縦割りになっているので、そのようなネットワークづくりを、目に見える形で整備していっていただきたいと思うんですが、いかがお考えでしょうか。","respondent":"太田品川区保健センター大井保健相談所長","answer":"今、発達障害の対応については、教育委員会のほうが中心になって行っておりまして、特別支援教育検討委員会を平成１６年から開催しており、そちらのほうに子ども支援センターの職員等、また保健所長も行きまして、同様に検討を行っております。","voiceIndex":85,"id":"exchange-039"},{"speaker":"菊地委員","kind":"質問","question":"先ほど区内の患者さんの数のところが出されていましたけれども、ちょっとこの数字のところでお聞きしたいんですけれども、先ほど出されていたのは認定された患者さんの数字でしたけれども、今回の新しい制度というのは、こういう枠組みをとにかく超えて、気管支ぜんそくを中心にした患者さんの医療費助成をしていこうという制度なんだと思うんですけれども、国民生活の基礎調査というのを見ますと。","respondent":"太田健康課長","answer":"患者数については、正直申し上げて、私ども正確な患者数というのは把握はし切れてございませんけれども、制度当初の東京都の昨年来の説明でいきますと、確実な数字としては７万７,０００人という数字を、説明会では私どもに説明をしたです。","voiceIndex":88,"id":"exchange-040"},{"speaker":"菊地委員","kind":"質問","question":"今、７万７,０００人という数字が正確な数字として説明されたということであれば、区内の患者さんの数というのもおわかりになるかと思うので、その辺をもう１度お聞かせ願いたいと思うんです。ですから、区内の実際の患者さんの数というのを、先ほど東京都のは発表があったということですので、そこからもわかるのかなと思いますので、その数を教えていただけますか。","respondent":"太田健康課長","answer":"区部と市部ということで単純に計算をしていきますと、区部で５万２,０００人ぐらいという推計が出てありますので、それを２３区で割り返せば、大ざっぱなあれですけれども、２,０００人から２,５００人ぐらいが申請されるのかなという予測は持っているところです。","voiceIndex":90,"id":"exchange-041"},{"speaker":"菊地委員","kind":"質問・要望","question":"それからこのぜんそくの発症要因のところなんですけれども、アメリカなんかでは１０年以上も前からＰＭ２.５、浮遊状粒子物質というんですかね、非常に細かい粒子の規制をやっていますけれども、この基準ができていった場合に、例えばアセスメントの考え方なんですけれども、中央環状品川線の建設工事が進んでいますけれども、この中でアセスが行われていますけれども。","respondent":"太田健康課長、田村環境課長","answer":"当然、医療費制度を立ち上げているのは東京都が都全域の関係から制度化をしたものです。都がまずは責任を持って、ホームページなり広報紙なりを使って周知をする。それと各医療機関のほうも既に説明をしていると聞いてあります。ＰＭの話ですが、環境アセスは東京都の環境アセス条例に基づいて数値も定まっていますので、事後的に数値が変わったからもう１回やり直しという考えはございません。","voiceIndex":92,"id":"exchange-042"},{"speaker":"菊地委員","kind":"質問・要望","question":"それから八潮のジャンクション、ここで集中的に汚染物質の垂れ流しが行われて、ＰＭ２.５そのものはぜんそくを誘発する原因だけじゃなくて、がんを誘発していく物質であるということも、研究調査の中で明確になっているわけですから、私は東京都に、まだ日本の基準が決まっていませんから、アメリカの基準をもってしてでも。","respondent":"田村環境課長","answer":"先ほどもご答弁したように、東京都の環境影響評価条例に基づいて、区のほうでもアセスを実施しておりますので、先ほどのＰＭの話、健康影響がどういうふうに出るのか、あと環境影響法という法律もありますので、その辺の国だとか都の動きを見据えないと。","voiceIndex":95,"id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"東京都に対してそれを要請することもできないんですよということなんでしょうか。当然のことながら、中央環状品川線で見れば、集中的に地域に排気されるということはわかっているわけですから、ですから、区ではできませんというのは、それはそれでいいですよ。そのことそのものも否定をされるということなんでしょうか。もう１度ここをお願いします。","respondent":"田村環境課長","answer":"先ほどもご答弁しましたけれども、健康影響被害が因果関係も含めてどういう形で出るのかということで、東京都の環境条例そのものが、因果関係を含め本当に必要性があるということで判断した場合には、それに沿って品川区も動きますけれども。","voiceIndex":97,"id":"exchange-044"},{"speaker":"菊地委員","kind":"質問・要望","question":"東京都もその危険性というのを認めて、都内の既存の測定局でこのＰＭ２.５の調査をやりますよと。全国７カ所でモニタリングをやりますと。当然のことながら、ここでそうした問題点が生まれてくるというのがはっきりしているわけですから、早い時期にここをきっちり押さえていくということをぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"２３３ページの環境衛生、犬の愛護、動物の愛護、環境衛生のところ、そして２３７ページ、未熟児養育医療費公費負担、先ほど説明の中で増えたという説明をいただいたんですけれども、これは背景というか、教えていただきたいと思うんですけれども。","respondent":"太田健康課長","answer":"１つはその部分で負担の割合が、適用になる方が多くなってきているということが１点あります。人数といたしましては、平成１６年で１６０名、平成１７年で１６８名、平成１８年で１９２名という形で、対象になる方自体も増えてきているという状況になってあります。","voiceIndex":101,"id":"exchange-046"},{"speaker":"大沢委員","kind":"質問","question":"お母さんの胎内にいるときからの指導も、区のいろいろな事業の中でされていると思うんですけれども、それの効果というか、これはそれぞれ子どもたちの特性があると思うんですけれども、多いということはあまり好ましくないことと私は考えますけれども、そこのところはどういうふうにとらえたらいいんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ただ現在、委員ご指摘のように、若干これは行き過ぎではないかという意見もありますので、今後専門家の意見などを十分に見ながら、必要な対策等がありましたら、これを検討していくという考えです。","voiceIndex":103,"id":"exchange-047"},{"speaker":"大沢委員","kind":"質問・要望","question":"私も医者ではないので、ここまででこの質問は終わらせていただきたいと思います。次に２３３ページに戻ります。シラミについてちょっと伺いたいと思います。私が伺いたいのは頭ジラミのほうです。子どもの中で、一、二年前でしょうか。去年でしょうか。局所的に集団発生をしたということを聞いております。自治体によってはこの頭ジラミについての対症方法をホームページ等に載せております。","respondent":"平澤品川区保健センター衛生課長","answer":"委員お尋ねの頭ジラミの件なんですけれども、東京都のほうで統計をとってございまして、平成１８年度につきましては１,１２５件の相談がございました。","voiceIndex":105,"id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"これは本当に感染症ということで病になっております。そこのところを現場でそういう知識を得るために引き出すというよりも、むしろホームページ、自分のデスク上で何か手だてがわかるような形を講ずるほうが、私は有効だと思うんですけれども、そこのところをいかがお感じになりますでしょうか、お答えください。","respondent":"平澤品川区保健センター衛生課長","answer":"委員ご指摘のとおり、頭ジラミ対策につきましては、薬剤に頼らず、洗髪、頭を洗うことが第一義ということで、これからも私どものほうでホームページ等を活用しまして、広報を広げていきたいと考えています。","voiceIndex":107,"id":"exchange-049"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにいたしましても、６月から１０月はピークだということでデータが出ておりますので、なるべく早急な対処をしていただきたいなと考えますので、よろしくお願いいたします。次に行きます。猫も一緒です。ただし猫の場合は数の把握はできません。起居を共にする動物であります。しかしながらこれがやはり生きるものである以上、人間の寿命の５分の１ということで犬の場合は聞いています。","respondent":"倉橋品川区保健所保健サービス課長","answer":"確かにアニマルセラピーという言葉もありますとおり、ペットとの触れ合いが心の健康に十分な効果があるということも言われているところです。このようなことも配慮しながら、犬をはじめとしたペットのことにつきましても、十分に配慮して対策をとっていきたいと考えております。","voiceIndex":109,"id":"exchange-050"},{"speaker":"大沢委員","kind":"意見","question":"いずれにいたしましても、失ったものの悲しみというものもありますので、動物も人間と同じように、心のケアをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-051"},{"speaker":"阿部委員","kind":"質問・要望","question":"私からは、２４５ページ、マイバッグ、２４９ページ、資源持ち去り防止対策、そして２５６ページの中小企業対策費全般、時間の都合にもよりますが、２５５ページの観光についても少々お伺いできればと考えています。この１年間で、何かするたびに、ちょっと冴えない、あまり使いたくないようなエコバッグらしきものをいろいろなところでもらうんですけれども、使わずにたまっちゃっているんですね。","respondent":"田村環境課長","answer":"ですから、これは買い手の問題なんですが、マイバッグを買ったら、かなり使い切ってもらうという取り組みをしていただかないと、マイバッグの取り組みは推進しても、マイバッグそのものが資源のむだ使いという形になるので。","voiceIndex":113,"id":"exchange-052"},{"speaker":"阿部委員","kind":"質問・要望","question":"２４９ページ、資源持ち去り防止対策なんですけれども、これは条例改正ということで、ぜひしっかりやっていただきたいと思うんですが、予算としては車とかステッカーということで、人についてはどのようになっているんでしょうか。どういった方が何人ぐらいでどういうことをなさっているのか教えてください。","respondent":"島袋品川区清掃事務所長","answer":"持ち去りパトロールは実効性を持たせるためにパトロール隊を編成しようと考えておりまして、現在、技能長クラス５名くらいで体制にあたりたいと思います。車については２台で、職員については５名で、主に集団回収の現場をあたりたいなと考えております。","voiceIndex":115,"id":"exchange-053"},{"speaker":"阿部委員","kind":"質問","question":"この５名の方というのは、新規にこのためにということなのか、それとも今いる現有勢力の中で時間を繰り出して何とかその５名に回ってもらうということなのか、どういうことでしょうか。","respondent":"島袋品川区清掃事務所長","answer":"現行の人員内で対応していく考えでおります。","voiceIndex":117,"id":"exchange-054"},{"speaker":"阿部委員","kind":"質問","question":"とすると、ただちょっと車で回って、「これはだめだからやめてくださいね」「はい、そうですか」というような感じのパトロールではないと思います。","respondent":"島袋品川区清掃事務所長","answer":"今、委員おっしゃったとおり、これは条例施行が７月ということなので、最初のときは５名のパトロール隊以外にうちの職員を使って、荏原と品川、両庁舎ありますので、大々的に強化月間としてやっていこうかと考えています。","voiceIndex":119,"id":"exchange-055"},{"speaker":"阿部委員","kind":"質問","question":"この策定委員会の方にもちょっとお目にかかってお話を伺ったんですけれども、このプランの策定に当たって、区内業者３万２,０００カ所以上の実態調査を、建設業からサービス業、小売業に至るまで実態調査を行って、それをベースとして産業振興プランをつくっているということなんですね。","respondent":"金子産業振興課長","answer":"新宿区の例を出されて、産業振興施策、プランをどういうふうに考えているかというお尋ねですけれども、私どもとしましては、今ちょうど基本構想に基づく長期基本計画を策定中であります。","voiceIndex":121,"id":"exchange-056"},{"speaker":"阿部委員","kind":"質問・要望","question":"長計の中でプランを立てていく、それから、実態については随時意見を聞いている、あるいは毎年要望を受けているというようなことだったと思うんですけれども、やはり今、例えば商店街がこの先どうなっていくか、長期的に不透明感がある、あるいは中小企業についてもそうであるといったようなときに、やはり抜本的かつ網羅的な実態調査に基づいた長期的なプランニングというのは。","respondent":"金子産業振興課長","answer":"この３万３,０００件のものをどうやって意向を収集するのが一番効果的なのかというのは、必ずしも全体にお聞きするのが妥当なのかどうかというのはわかりませんけれども、そういう意味では、区内の企業の意向というものも適切に把握する中で。","voiceIndex":123,"id":"exchange-057"},{"speaker":"阿部委員","kind":"意見","question":"それで、今、意向の収集を全体にかけることがどうなのかということもありましたが、例えば新宿のほうでも、これは大学などに委託をして、それはアンケート調査としてちゃんとサイエンスに基づいたものをやっているようですので、必ずしも区役所だけのマンパワーだけでやる必要はないかと思います。そういったことも含めて、ぜひ長計の中でしっかりとやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-058"},{"speaker":"武内委員","kind":"提案","question":"２３３ページの薬事衛生許可および監視指導に関連して、昨年の決特のときにもお聞きしたんですが、後発医薬品、ジェネリック医薬品の件ですけれども、今回の４月から医療の診療報酬の改定の流れの中で、これが新たに動きがあったと聞いているので、その説明をお願いしたいのと、２３７ページの歯科衛生相談に関連して、これも診療報酬改定の流れの中で、小児用の入れ歯。","respondent":"山岡品川区保健所衛生課長、倉橋品川区保健所保健サービス課長、田村環境課長、平澤品川区保健センター衛生課長","answer":"どういうふうに変わるかと申しますと、平成１８年４月に一部変わりまして。第２点の歯科矯正および小児義歯の適用症の拡大についてですが、国のほうからの説明によりますと、適用症の拡大といたしまして。現在、経済産業省の資源エネルギー庁が進める省エネルギーの政策ではありますが、ＥＳＣＯ事業の問題点としては、補助金申請の手続、事業期間の問題。中国産餃子についてお答えいたします。現在の保健所の対応状況ですが、自主回収の回収状況について毎日報告させているところです。","voiceIndex":128,"id":"exchange-059"},{"speaker":"武内委員","kind":"提案","question":"ジェネリックについては、今ご答弁いただいた内容が改定になったということなんですけれども、その中で今度、比較的、前回私が質問したときは、これが本当に先発薬と比べてどうなんだという観点で質問をして、厚労省のほうでこういう形で進めているということなので、おそらくこれはいわゆる区としても薬の分がジェネリックが使われることによって下がれば。","respondent":"山岡品川区保健所衛生課長、倉橋品川区保健所保健サービス課長、田村環境課長、平澤品川区保健センター衛生課長","answer":"こういう機会を通して周知してまいりたいというふうに考えております。適切な周知方法を考えて対策をとっていきたいと考えております。私のほうからＥＳＣＯに関する啓発活動ですが、先ほどもご答弁申し上げましたように、中小企業対策について現在見直しをしているということですので。このファックスに基づきまして回答しています。","voiceIndex":133,"id":"exchange-060"},{"speaker":"武内委員","kind":"質問・要望","question":"ジェネリックについては、区民の方にも、結構知らない方がいると思うので、何かの形でやっぱり広報していくことが大事なのかなと思いますので、もう１回そのところをお願いしたいのと、あと、入れ歯についてはわかりました。ぜひ有効な広報をしていただければというふうに思います。そのような流れの中で今後どうなっていくのかなというのも１つあるので、それは参考に教えていただければと思います。","respondent":"山岡品川区保健所衛生課長、鷹倉区民課長","answer":"委員おっしゃるように、その部分も大事にしていきたいと思います。区の広報紙あるいはホームページ等を活用して、どういう形ができるか今後検討してまいりたいと思います。よろしくどうぞお願いします。消費者相談と食の安全をつかさどる保健所と連携を強化して、今後、区民の食の安全を守っていきたいと、このように考えてあります。","voiceIndex":138,"id":"exchange-061"},{"speaker":"藤原委員","kind":"質問・要望","question":"２５１ページの普及広報費について幾つかと、２５９ページ、商店街についてお伺いしますが、まず初めに、広報費についてですが、平成１９年度の予算を見ますと、この中にメール配信サービスと清掃車両運行状況システム研究費というのがあるんですけれども、この平成２０年度予算書にはこの項目がないんですけれども、その理由について、この２点についてお伺いしたいんですが。","respondent":"秋山資源循環推進課長、金子産業振興課長","answer":"ＧＰＳに関しましてですけれども、ＧＰＳについては、今年度、明治大学と一緒に検討いたしましたけれども、収集車両と、よく使われているバスとかタクシーでＧＰＳを使って効率化をしているわけですけれども、ちょっとバス。商店街に関して３点のお尋ねだと思いますが、まず１点目は、予算関係についてまとまらないかということなんですけれども、冒頭、企画財政課長がご説明申し上げたとおり、今年は若干予算がわかりやすいように整理しています。","voiceIndex":142,"id":"exchange-062"},{"speaker":"藤原委員","kind":"質問・要望","question":"いろいろな意味で。地域の密着ということがあると思うのでしたら。３億８,０００万円というのは何と表現していいかわからないですけれども、そんなものかという思いもちょっとあります。特に今度、区長が高橋区長と違うところは、小規模な商店街に対しても手厚く助成をしていくというような特徴がちょっとあるんじゃないかなと思うんですけれども、その辺についてはいかがでしょうか。","respondent":"岩崎環境清掃事業部長、金子産業振興課長","answer":"メール配信のケースは、明治大学が開発したメール配信ソフトをただで品川区役所が使うのに、何か頃合いの領域がないだろうかというところから始まって、とりあえずモデル的に清掃事業でできないだろうかということで。小規模商店街についての支援のお尋ねですけれども、ご案内のとおり、従来から商店街の助成に関しては、基本的には都と区で３分の２を負担し、３分の１を商店街が負担してくる、つまり。","voiceIndex":145,"id":"exchange-063"},{"speaker":"原委員","kind":"質問","question":"私のほうからは、２６３ページ、大崎駅周辺ものづくり産業支援施設検討経費をより具体的に。それで、時間があれば２６１ページ、国際取引支援助成金等をお伺いしていきたいと思います。","respondent":"金子産業振興課長","answer":"近年、産業技術大学院大学というものが区内に開設されまして、こことの連携を強めているところなんですけれども、そういう意味で、最近の京浜地区の中小企業の動向、また品川区内の中小企業、さらには、大きな企業の動向も踏まえて。","voiceIndex":149,"id":"exchange-064"},{"speaker":"原委員","kind":"質問","question":"そうしますと、もう少し具体的なところで、これは地域、特に中核的なものを置いていくとか、地域的に具体的な中核のポイントというか、場所を置いていくとか、それから、内容的なものなんですけれども、施設的なものの概略等がお決まりになってというか、区としての見解をちょっと教えていただければと思うんですけれども。","respondent":"金子産業振興課長","answer":"確かにこの施策の名前のとおり、大崎駅周辺では非常に大規模な開発がされていまして、なおかつ大崎駅というのは、先ほど申し上げました京浜工業地帯発祥の地でありますので。","voiceIndex":151,"id":"exchange-065"},{"speaker":"原委員","kind":"質問","question":"なぜ二度似たような質問をしたかといいますと、明日の土木のほうの質問予約みたくなってしまうんですけれども、五反田のにぎわいゾーンと、その辺との関係を私の頭のほうにあるものですから、施設のあり方、検討をいろいろとそういう意味では、区、再開発組合、それからあとは地域住民等なんでしょうけれども、施設自体がどうなのかということ、単なるものをつくっていく施設、二度ほど京浜関係という。","respondent":"金子産業振興課長","answer":"具体的な詳細な検討は平成２０年度になってからと考えておりますが、今の段階でいろいろ考えられることにつきましては、例えば現状を踏まえますと、委員もご指摘のとおり、なかなか区内の工場というものが、区外あるいは海外に転出している。","voiceIndex":153,"id":"exchange-066"},{"speaker":"原委員","kind":"質問・要望","question":"この質問は、要望という形になろうかと思いますけれども、あのエリアというのは、ソニー、全体的には動きますけれども、それとあと、ＩＭＡＧＩＣＡですとか、これは世界最高の技術を持った企業だと思いますので、その辺のところともいろいろと。これは要望という形でお願いをしてまいります。","respondent":"金子産業振興課長","answer":"国際取引支援の関係と、ＣＳＲの関係なんですけれども、私どものこの支援事業に関しましては、区内の中小企業が特に最近、工業関係、大手が東アジア地域、あるいは東南アジア地域に進出しているというところから。","voiceIndex":155,"id":"exchange-067"},{"speaker":"原委員","kind":"質問・要望","question":"そうしますと、具体的に日系企業、アジアということなんですけれども、これはポイント的には、日系企業という形で限定をしていいのか、もしアジア地域で具体的な国名等がありましたらお教えいただきたいのですけれども。","respondent":"金子産業振興課長","answer":"そういう意味では、こういう地域を中心として、あるいはさらに今後の国際情勢等も踏まえた上で、ポイントを絞りながらこの事業については実施していきたいというふうに考えてあります。","voiceIndex":157,"id":"exchange-068"},{"speaker":"南委員","kind":"質問・要望","question":"２３５ページの新生児等訪問指導、そして２４７ページの緑化推進費、この２つで伺いたいと思います。新生児等訪問指導で、新生児訪問が１,６６０件、産婦訪問も同数計上されていますが、この間、こういう事業をされていて、どのような相談内容、どのような状況が今まであったのかということをちょっとまず教えていただきたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"新生児訪問指導についてのお尋ねです。１点目は、どういうふうなというか、ご相談というか、どういうふうな指導をしているかということのお尋ねです。","voiceIndex":160,"id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"私も去年の決算委員会のときにも取り上げましたけれども、出産にかかわる産科医師の減少が非常に社会的な問題になっているわけですけれども、その問題を取り上げて質問させていただきましたけれども、なかなか品川区独自で整備できる問題ではありませんけれども、やっぱり半年近く、数カ月たっている中で、区としてお医者さんを増やすためにどういう働きかけをされてきたのか。","respondent":"倉橋品川区保健所保健サービス課長、松代管理工事課長","answer":"１点目の医師の確保策ですが、医師自体の総数を増やすというのは、これはなかなか区単位では難しいことでございまして、国のレベルで中長期的に専門医の養成確保、医学部の定員増などで対応していくべきものと考えております。加えて、今現在進めております新・水とみどりのネットワーク構想、それを新しい視点で多様な手法を用いながら区民の皆様とさらに増やしていこうと、そういうものを今現在いろいろな事業。","voiceIndex":162,"id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、本当に対応をしっかりしていただきたいということと、それから、出産祝い金をぜひ創設するべきだということをちょっと改めて申し上げておきたいというふうに思います。その点で、どういうふうに緑化推進のところではどうなのかということをちょっと伺いたいんですけれども、時間の関係があるので十分言い切れませんけれども、答弁をお願いします。","respondent":"倉橋品川区保健所保健サービス課長、松代管理工事課長","answer":"医師について答えします。区としての働きかけですが、平成１９年６月に東京都が東京都地域医療対策協議会というものを設置してございまして、こちらに区の代表としての保健所長も加盟して協議しております。地球温暖化というのは、地球全体の部分と、まちづくりに関連する、そういった部分とあろうかと思いまして、私どもは身近なところでそういう温暖化対策を進めていきたいというように考えているところです。","voiceIndex":165,"id":"exchange-071"},{"speaker":"若林委員","kind":"質問・要望","question":"２２７ページの各種助成金の中の公衆浴場、これは２６１ページも絡んでくるかと思います。それから、２４５ページの環境ＩＳＯに関連して伺います。それから、環境ＩＳＯのほうですが、そもそもなんですが、まずこのＩＳＯというのは、そもそもどういうシステムなのか教えていただきたいというふうに思います。","respondent":"太田健康課長、田村環境課長","answer":"公衆浴場の廃業の数字についてですけれども、平成２０年２月８日で今年度も１カ所公衆浴場が廃止届を出されております。これで現在の公衆浴場数３６カ所ということになってあります。環境ＩＳＯの関係ですが、ご存じのとおり、環境ＩＳＯは国際規格で１４００１ということで、特に総合庁舎、出先を含めてやっておりますが、環境マネジメントシステムの円滑な運用と管理を実施して。","voiceIndex":169,"id":"exchange-072"},{"speaker":"若林委員","kind":"質問・要望","question":"経営努力をさらにしていただいて、また区の支援もしっかりして利用していただく中で元気になって地域の方のための公衆浴場であっていただきたいなと思っている中で、１つ、業界の方からお話を聞いたのは、やはりそういう中で重油高が大変に厳しい状況だということで、１つ教えていただきたいのは、例えばこの３６カ所の中で。","respondent":"太田健康課長、田村環境課長","answer":"補助経費は２分の１で施設当たり２００万円ということになってありますので、これを受けまして、区のほうにおいても、設備補助要綱の中で公衆浴場施設の改修ならびに安全器具等の設備に必要な経費という項目がありますので。お尋ねのコピー用紙の増ですが、やはりこの辺が環境ＩＳＯのときに数値目標を毎回毎回何％減というのも、当然、いずれ限界が来るだろうということですが、やはり庶務担当課長会だとか、そのようなときにできるだけ裏面コピーを利用する。","voiceIndex":172,"id":"exchange-073"},{"speaker":"若林委員","kind":"質問・要望","question":"ＩＳＯのほうはよろしくお願いいたします。公衆浴場のほう、そうしますと、確認ですが、都の制度と区の制度を同時には使えないという今の、そういう言い方ではないんですね。余っているものは有効に使っていただきたいなという思いがあるんですが、そこだけ一言お願いをいたします。","respondent":"太田健康課長","answer":"東京都全体で重油は、公衆浴場の約２０％が使っているみたいですので、大体７カ所ぐらいかなと思います。それから、今のご答弁ですけれども、区市における設備補助との併用も可ということになってありますので、区においても有効に補助金を活用していきたいです。","voiceIndex":175,"id":"exchange-074"},{"speaker":"市川委員","kind":"質問","question":"時間がありましたら、２４５ページの地球にやさしいお店発見経費、これについて伺います。乳がん検診に特化してお聞きするんですけれども、実際に検診率、受診率か上がらないと意味がないと思いますが、品川区の乳がん検診率の目標値、それから直近で結構ですので、受診率がどれぐらいだったのか、また、受診率向上のためにどのような取り組みをしているのかを伺います。","respondent":"太田健康課長","answer":"区民健診の中に一連のがん検診等についてのお知らせも同封をさせていただいています。それから、年に１回、乳がん自己診断という形での自己の検査法という簡単なパンフレット等も送付をさせていただいているところです。","voiceIndex":178,"id":"exchange-075"},{"speaker":"市川委員","kind":"質問","question":"今は乳がん検診専門に女性技師に求人が多くありますので、品川区もぜひ積極的に女性の検査技師を導入していただくように、ぜひ医師会のほうに働きかけてほしいというふうに思います。検査技師が女性ということが口コミも含めて広がれば、確実に受診率アップのほうにつながるというふうに思いますが、いかがでしょうか。区の見解をお聞かせください。","respondent":"太田健康課長","answer":"昨年９月から検診車で委託をしている予防医学協会については、ご指摘のとおり、技師については、現在、女性で対応していただいているです。両医師会については、残念ながらといいますか、現状では技師については男性だです。","voiceIndex":180,"id":"exchange-076"},{"speaker":"市川委員","kind":"質問・要望","question":"マンモグラフィーの検査技師を女性にして、女性に非常に求人も多く求められているということも聞きますので、企業の検診のほうは、そういう受診者の声をしっかりつかんでいるのではないかなという証だと思いますので、ぜひよろしくお願いいたします。ワンルームマンションのごみの出し方が悪いということをよくまちの人の声として聞くんですけれども、実状、実際のところはどうなんでしょうか。","respondent":"島袋品川区清掃事務所長","answer":"分別変更モデル実施経費の内容ですけれども、印刷費と区広報費の関係の印刷物の経費がほとんどでして、３,３００万円ほど印刷経費がということです。駅のポスターの掲示とか、こういうものを考えているところです。","voiceIndex":182,"id":"exchange-077"},{"speaker":"市川委員","kind":"質問・要望","question":"これに対する見解を伺うのと同時に、それから啓発活動の１つとして、一番品川に転入される方の多い、そういう時期があるかと思うんですけれども、この時期に環境センターの前に相談コーナーを設置して、分別方法の説明に当たるというのはどうでしょうか。地道に理解する人を増やす啓発活動で、ごみの経費の節減にもつながるのではないかというふうに思いますので、このことのご見解を伺います。","respondent":"島袋品川区清掃事務所長","answer":"このデザインにつきましては、今年度の予算でプロポーザル方式でデザイン会社に委託しました。それで、資源循環推進課の職員と清掃事務所が一緒になってチームで今、デザイン等を検討しています。","voiceIndex":184,"id":"exchange-078"},{"speaker":"市川委員","kind":"質問・要望","question":"それから次に、２５７ページの消費生活相談についてなんですけれども、消費相談機能の強化ということで、電話相談時間の延長と、それから相談員の増員ということが予算化されていますけれども、この相談員をされる方はどういう方が相談員となるのかと、それから、相談員への研修の内容と回数について伺います。","respondent":"鷹倉区民課長","answer":"そこに派遣するような形で専門相談員の識見を高めている。あるいは、日常的にはそれぞれの相談員がお互いに勉強会的なものを持つような形で、かなり幅広い相談分野がありますので、日々いろいろ勉強していかなければ対応できていかないなというふうに考えてあります。","voiceIndex":186,"id":"exchange-079"},{"speaker":"市川委員","kind":"質問・要望","question":"被害の傾向や相談処理に関する幅広い情報を積極的に提供してもらうように、また、相談員の問題発見能力などの資質向上に役立つ研修の実施などをぜひ都に働きかけて相談員のスキルアップに努めていただきたいというふうに思っているんですけれども、この点のご見解をお願いいたします。","respondent":"鷹倉区民課長","answer":"ただ、うちの場合、専門性を要するということで、一番長い人で２０年近くやっていただいているような方がいらっしゃいます。やはり継続的に品川区のために働いていただく方を確保しているです。それから、身近な部門との連携、あるいは東京都との連携というお話です。","voiceIndex":188,"id":"exchange-080"},{"speaker":"市川委員","kind":"質問","question":"すべて非常勤というお答えだったんですけれども、常勤の方が入っていれば内容についても区のほうで把握ができるというふうに思うんですけれども、すべて非常勤という場合の区との連携というのはどういう形をとっているのかということを１つお聞きするのと、それから、時間がありますので、２４５ページの地球にやさしいお店発見経費について何点かお伺いします。","respondent":"鷹倉区民課長、田村環境課長","answer":"専門の相談員は６名とも非常勤と申しました。ただ、消費者センターの所長以下、正規の職員が３名います。その者との連携をきちっとした形でやってあります。地球にやさしいお店発見経費のうち、メール配信サービスについての経費はゼロです。","voiceIndex":190,"id":"exchange-081"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、２４１ページの公害のほうとあわせてなんですけれども、いろいろなインフルエンザだけに限らず、インフルエンザ菌ですとか、いろいろなウイルスが何百種類もあると思うんですけれども、そういった１つ１つの予防をしていくという予防接種等は本当に必要なことで続けていただきたいと思うんですが、いろいろな大気汚染ですとか、ここ数年では中国から黄色い砂が飛んでくる黄砂ですとか。","respondent":"太田健康課長、倉橋品川区保健所保健サービス課長","answer":"これについては、東京都の中の協定で他の区、市と同一協定を結んでいるところです。これで約４,４００円ということで、ご本人は２分の１で２,２００円の負担で１回分は受けられる、こういう形になっているところです。ですから、もともと呼吸機能を高めるという意味では、運動など、それから生活習慣など、基本的なところが大事になりますし、感染症を予防するという意味では、インフルエンザなど予防できる病気につきましては予防接種をするということ。","voiceIndex":194,"id":"exchange-082"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いします。次に行きます。それで、４０歳以上５００件で、対象者が４０歳以上の喫煙者ということなんですけれども、喫煙しない方への受動喫煙とか、そういったところで対象者を決めていく、どういうふうな決め方をしていったのか、がんになる傾向だけをとらえて対象者を決めていったのか、その辺を教えていただきたいと思います。","respondent":"太田健康課長","answer":"対象者については、喫煙者ということで企画財政課長のほうから説明がございましたけれども、私どものほうでは、委員ご指摘の受動喫煙、あるいは過去に喫煙経歴があった方等も含めて、多少柔軟な自覚症状があればということでの方向で考えているところです。","voiceIndex":197,"id":"exchange-083"},{"speaker":"本多委員","kind":"質問・要望","question":"罹患率がかなり決め手だと思いますが、ぜひ拡大を目指していただきたいと思います。がん検診の管理システムということで、受診の推奨についてお聞きしたいんですけれども、検診の電算システムの導入ということなんですが、これについて概要を教えていただきたいと思います。","respondent":"太田健康課長","answer":"それで、私どもといたしましては、今年度からがん検診で有所見があった方について、区のほうで検診を受けて有所見、疑いがあるとかということになったときに、精密検査をする、次の段階の二次病院に行ったときに、その結果についての追跡調査もしていこうということで、今回。","voiceIndex":199,"id":"exchange-084"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、先ほど来、受診率の目標値等を上げていく、受診率を上げていくということなんですけれども、そういったいろいろな追跡調査等を含めて充実というか、それだけ受診が上がればいいと思うんですが、それにあわせて発見率も上げていっていただきたいと思うんですけれども、がんセンターの発見率とか、どうしても行政のやる取り組みの発見率とか、比較されがちなんですけれども。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ということで、運営上のノウハウも含めました全体のシステムを改善していくことが手法のみならず検査の成績を上げるには必要なことと考えておりますので、現在の制度管理委員会の検討を中心といたしまして、区のがん検診の制度を高めてまいりたいというふうに考えております。","voiceIndex":201,"id":"exchange-085"},{"speaker":"本多委員","kind":"質問","question":"最後に、２３１ページの区民健診で１点だけお聞きしますが、平成２０年度から制度が変わりまして、特定健診になるわけですけれども、ここでいう区民健診というのは、医療保険未加入者ということで限られた方なんですけれども、これまでの品川区医師会管内、荏原医師会管内の実施する医院という表があったと思うんですが、実際その表で両方とも１００施設以上の品川、荏原、両方出ていてわかりやすいんですが。","respondent":"太田健康課長","answer":"品川区医師会、荏原医師会ともよくご相談をして、できることがあれば対処していきたいというように考えてあります。","voiceIndex":203,"id":"exchange-086"},{"speaker":"渡部委員","kind":"質問・要望","question":"私のほうは、２２８ページ、予防費の中の隣の感染症予防費、予防接種費等をお伺いして、２３２ページの環境衛生費の中では、定例会でうちの会派の議員から質問させていただきました、犬の登録の件と、同じページの食品衛生許可監視指導の部分。２２８ページの予防費の部分で、まず予防接種のところからお伺いしたいと思います。お教えください。お願いします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"ただ、別に国のほうのＱ＆Ａで、２回既に接種しているんだけれども、３回目の接種を希望する方についてはこれを妨げないといいますか、接種してもいいというＱ＆Ａが来ておりますので、そのように対応する予定です。","voiceIndex":206,"id":"exchange-087"},{"speaker":"渡部委員","kind":"質問・要望","question":"何かまた違う使い方があるのかなと思ったので、その部分だけご答弁をもう一度お願いしたいのと、あと１つ、この感染症に関連して、休み前にほかの委員から質問がありまして、たしか保育園に登園する際、インフルエンザで休んだときに登園する際、診断書ではなくて、登園証明書のようなものをというような話だったと思いますが、改めてここで確認をさせていただきたいんですが、例えば区立の施設。","respondent":"倉橋品川区保健所保健サービス課長、小林保育課長、長田教育次長","answer":"新型インフルエンザの予算倍増というのは、主に防護服などを１カ月程度以上、対策をするのに必要な設備。一定の疾病につきましては、他の園児に影響があるような場合、もう既にその病気が一定快方に向かって急性期を過ぎて。ただ、医者にかかって、もう先ほど保育課長のほうからも話がありましたとおり、もう人にうつらないというような部分につきましては。","voiceIndex":208,"id":"exchange-088"},{"speaker":"渡部委員","kind":"確認","question":"もう１回、完治していますよということの確認に行きましたということで、医者に行っている実績があれば、それは保護者が書いてまた通学すればいいということですか。確認だったのでありがとうあります。次に行きます。２３２ページの環境衛生費の中で、犬の登録の部分で、日曜開庁のときにぜひこの登録事務をやってもらえはしないものだろうかと質問をさせていただきました。","respondent":"太田健康課長","answer":"それに転入に付随いたしまして、私どもで言えば、妊産婦の方、母子保健手帳とかについては、二度手間をかけないという観点から実施をしているものですので、以上申し上げた点から申し上げて、犬の登録事務については、現在のところ考えていないところです。","voiceIndex":212,"id":"exchange-089"},{"speaker":"渡部委員","kind":"質問","question":"重ねてのお願いでしたが、わかりました。その中で１つ新聞報道等であります保健所を国からの連絡体制の中で３６５日２４時間の連絡体制をとるというような報道があったと思うんですが、この辺というのが、これが行われることによって、例えば保健所の体制が変わるとか、業務が何か変わってくるとかあるのでしょうか。そこだけ１つお聞かせください。","respondent":"平澤品川区保健センター衛生課長","answer":"現在、東京都では、ひまわりという制度がございまして、２４時間、３６５日、食中毒事故が起こった場合には、ただちに保健所の衛生課長のほうに通報するようなシステムが整っておりますので、そちらのシステムで行っていくところです。","voiceIndex":214,"id":"exchange-090"},{"speaker":"渡部委員","kind":"確認","question":"僕も伺おうと思っていましたこの人数の部分ですとか、新たな制度の部分、わかりました。一つだけ確認なんですけど、今、１８歳未満で助成されている方々が、例えば今１７歳の方が今度１８歳以上になると、新たに登録し直しなんでしょうか。そのままスライドしてというんでしょうか、例えば今、医療証を持っている方というのは、どのような手続きをすればよろしいんでしょうか、教えてください。","respondent":"太田健康課長","answer":"１８歳未満のお子さんで、今、医療証をお持ちになっている方が１８歳になった場合には、これは新たに数カ月前、今、都の方で検討中ですけれども、切れる前の一定期間前から、１８歳の大人の部分で申請をしていただくということになっております。","voiceIndex":216,"id":"exchange-091"},{"speaker":"渡部委員","kind":"質問","question":"２５７ページの消費生活相談の部分についてお伺いします。６名の方がこれから相談員として従事されるわけなんですが、一つ、連絡を様々なところで密に取り合って対応されていくということなんですね。これって、実際、僕は不勉強で申しわけないんですが、あの消費生活展に行ったからこれをもらえたんですけれども、例えば普通の一般の人たちがこれを手に入れる方法があれば教えて下さい。","respondent":"鷹倉区民課長","answer":"地域センターだとか出先の施設にそれぞれ一定の部数を置いてありますので、ぜひそういう身近なところでもらっていただければと思います。当然、消費者センターにも問い合わせていただければ、郵送等も対応していきたいと考えています。","voiceIndex":218,"id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"一つだけ伺います。この消費者センターに連絡がありました、例えば家庭用品の件だとか、食品の件だとかあると思うんですが、これが一民間の会社、時間がないです。すみません、改めします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-093"},{"speaker":"川西委員","kind":"質問・要望","question":"２３１ページ、区民健診。この金額の算出の仕方というのは一件算定なのか、あるいは昭和大学病院とどういうふうな契約内容なのか教えていただきたいのと、それから一般で救急で行きますと、いすで座って待っていられる状況だと、１時間から１時間半ぐらい待つんです。ですから保健所・保健センター両方で扱う健診の対象人員が減ってきて、機能と職員の皆さんの活躍はどういうふうに移っていくんでしょうか。","respondent":"太田健康課長、倉橋品川区保健所保健サービス課長","answer":"１点目の小児平日夜間、それから土曜日の夜間診療についてお答え申し上げます。基本的には１日の単価で積み上げてあります。もし、この事業のことでしたら、保健所・保健相談所で月に１回以上実施しています。","voiceIndex":222,"id":"exchange-094"},{"speaker":"川西委員","kind":"意見","question":"そうしますと、仕事の量は減らないということでいいんですね。それで、私、保健センターで健診を受けている１人なんですけれども、見ていますと、５０人以下の事業所を対象に、栄養指導から全部していらっしゃるんですよね。とても熱心にやっていただいているなということは、日ごろから感謝しております。一言申し上げておきたいと思います。ここだけはっきりと。","respondent":"太田健康課長","answer":"現在、荏原医師会でお願いしていますのは７時半から１０時半までですけれども、４月１日以降については、昭和大学とともに、両医師会の小児科医師も参加をしてやっていただけることになっておりますので、８時から１１時という時間帯になる予定です。","voiceIndex":225,"id":"exchange-095"},{"speaker":"川西委員","kind":"質問","question":"１時間差がありますね。は救急医療に頼るしかないということで、これでも新しい制度ですからよろしくお願いします。先ほどの説明のときに、ちょっと耳に残っているんですが、未熟児の対象が増えてきているというふうに伺ったんですが、間違いでなければ、妊娠中の母体保護の問題なのか、若いときからの栄養のとり方の問題なのか、増えているとすれば、その辺どういうふうに分析していらっしゃるか伺います。","respondent":"平澤品川区保健センター衛生課長、倉橋品川区保健所保健サービス課長","answer":"区内の助産所の数です。平成１９年１２月末現在ですが、７施設あります。こちらの施設につきましてはすべて無床、ベッドを有してございませんので、出産の取扱はやってございません。ただ、この評価につきましては大変難しいところがございまして、体重だけが未熟性を評価するものではありませんで、例えば週数がそれなりに行っていれば。","voiceIndex":227,"id":"exchange-096"},{"speaker":"川西委員","kind":"質問","question":"医学の専門家の立場から、若いときからの栄養摂取とか、妊娠中の栄養摂取とか、そういう健康な母体を養うという点では、今の社会的状況というのはどういうふうに認識されているんでしょうか。中・高・成人になるともっと好き嫌いが激しくなって食べなくなるという現況があって、母体に影響するんじゃないかというふうに、これは素人考えですが、一言だけお考えを伺いたいと思います。","respondent":"倉橋品川区保健所保健サービス課長","answer":"これは社会的に遺伝するということで、子どもには伝わりますので、委員ご指摘の食事の重要性、大変重要であると認識しております。","voiceIndex":230,"id":"exchange-097"},{"speaker":"川西委員","kind":"質問","question":"今後期待します。次に移ります。２４５ページ、低公害車購入等助成、これの低公害車というのは何を指すのか伺います。","respondent":"田村環境課長","answer":"低公害車ですが、低公害車は、まず一つが粒子状物質減少の装置装着助成ということで、対象となるのは中小企業者あるいは個人事業者の３.５トン以上８トン以下のディーゼル自動車を対象としているものです。","voiceIndex":232,"id":"exchange-098"},{"speaker":"川西委員","kind":"質問・要望","question":"今の内容はわかりました。ＯＢ会というのがありまして。そこで、三十数万円かけると、ガソリン車をＬＰＧ車に変えることができる。そういう費用を出しても、２年たてば元をとっちゃうと言いますか、ガソリンよりＬＰＧは安いですからね。今後、ＬＰＧを区有車にも取り入れる、あるいは三十数万円の補助を考えていただくように、心から要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-099"},{"speaker":"松澤委員","kind":"質問・要望","question":"短く２点お聞きをしたいと思います。１点目が５款産業経済費に関連いたしまして、品川区内の商店街数の推移と商店数の推移、この５年ぐらいをお知らせいただきたいと思います。","respondent":"金子産業振興課長","answer":"平成９年ぐらいからの推移を申し上げますと、平成９年が３,８５０、平成１１年が３,８１８、平成１４年が３,４８０と、そういう意味では漸減傾向にあります。","voiceIndex":237,"id":"exchange-100"},{"speaker":"松澤委員","kind":"質問・要望","question":"商店街数が変わらずに来て、ここのところ増えている。けれども、商店数は、これは２割ぐらい減っているということになるんでしょうか。中身の件についてですけれども、２６１ページ、商店街連合会に２７０万円の助成、商店街振興組合連合会に５０万円の助成ということですけれども、この内容についてちょっとお知らせいただきたいと思います。","respondent":"金子産業振興課長","answer":"それから商店街連合会の補助金なんですけれども、こちらの方は、商店街連合会の実施する各種研修等々といった連合会自体の事業に対して助成を行っているものです。","voiceIndex":239,"id":"exchange-101"},{"speaker":"松澤委員","kind":"質問","question":"各種研修事業ということですか。そうすると、商店街連合会の中の職員の給与というんでしょうか、それはどちらから出ているんでしょうか。","respondent":"金子産業振興課長","answer":"商店街連合会、今、事務局員が常勤で３名おりますが、こちらの人件費に対して直接補助をするというものはございません。私どもとしましては、この事業の助成金のほかに、例えば「しながわの一番店発見プロジェクト」など、こういった事業を商店街連合会の方に委託をしております。","voiceIndex":241,"id":"exchange-102"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。当然のことながら商店街連合会ですから、各商店街から会費として上がってくる、それから払っている。続きまして２５９ページ、商店街活性化推進事業の中の商店街施設大規模整備助成についての内容と、同じく小規模商店街活力づくり支援事業、幾つかありますけれども、この事業内容をちょっとお知らせいただきたいと思います。","respondent":"金子産業振興課長","answer":"それから２点目の、小規模商店街活力づくりの方ですけれども、まず、再生モデル事業委託ですが、これにつきましては、今年度の新規事業で、小規模商店街の中で希望する商店街をモデル地区に選定しまして、専門家を派遣して、商店街の実態調査、あるいはニーズ調査等々。","voiceIndex":243,"id":"exchange-103"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは内容的には何なのかというはっきりしたものが決まっているんでしょうか。電線地中化、いろいろありますが、その内容を教えていただきたいのと、再生モデル事業委託、これも専門家による支援という話は伺っているんですけれども、これもモデル事業をするんだと、ある程度ここというところが決まっているんでしょうか、その点をお聞きしたいと思います。","respondent":"金子産業振興課長","answer":"小規模商店街再生モデル事業の方ですけれども、小規模商店街、品川区内、数としてはかなり多うあります。ターゲットを既に決めているのかというふうなお話ですけれども、小規模商店街に対して様々ご意見伺う中で、希望をとって選定していきたいと考えているところです。","voiceIndex":245,"id":"exchange-104"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点目ですけれども、これは４款衛生費、２項環境費なんですけれども、品川区の気候変動というんですか、地球温暖化に対する取組み、いろいろあるんですけれども、どういうような形で取り組んでいるのかについてお聞きしたいと思います。","respondent":"田村環境課長","answer":"それともう一つは、品川区もＣＯ２の排出事業者としてかなりの規模ですので、品川区の中で率先行動として、ＣＯ２削減にどういうふうに取り組んでいくかです。","voiceIndex":247,"id":"exchange-105"},{"speaker":"松澤委員","kind":"質問","question":"いろいろ取り組んでいるのはわかりました。何でなんだろう。今、一番大きな問題になっている環境問題の中で、環境課が全然主催していなくて、省エネ型が道路公園課ですね。立会川の浄化が下水道河川課。バーチャル案内人が紹介するエコ住宅、これは環境課なのかな。なぜこのような形にいろいろな課にまたがってしまっているのか、その辺をお聞きしたいと思います。","respondent":"田村環境課長","answer":"それを環境課の方で集約して、一定のＰＲも含めてやるべきだろうということで、来年度予算のときに私の方でご説明して、集約しよう、そしてＰＲしていこうというような、取りまとめ役というか、連絡調整役をやって。","voiceIndex":249,"id":"exchange-106"},{"speaker":"松澤委員","kind":"質問・要望","question":"全庁的なもので頑張っているということですけれども、確かに、今、課長がおっしゃったように、しっかりと品川区環境課ここにありということで頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"私の方からは、２３３ページ、犬の登録予防注射および動物の愛護に関連して。第１点目ですが、午前中もアニマルセラピーの話とか、ペット登録の義務化について、先ほども質問がありましたけれども、ここでうたってあります動物の愛護という点につきまして、飼い主のモラル、あるいはいろいろな啓発をされていると思うんですが、もう少し掘り下げて、どういうことをやられているかお伺いいたします。","respondent":"山岡品川区保健所衛生課長","answer":"これは、私どもでやっている事業は、直接飼い主の方に参加していただいて講習会、あるいはセミナー等をやる事業、それからパンフレット等をつくって飼い主の方に読んでいただく、それ以外に広報、ホームページ等を利用して、広く周知を図っていく。","voiceIndex":253,"id":"exchange-108"},{"speaker":"山路委員","kind":"質問・要望","question":"東京都の事業ですので、それに増して区でも対応をお願いしたいということでお願いいたしました。本年は、この身体障害者補助犬法が改正になります。４月から施行、そして１０月から義務化される。今回の改正法は、就労の拒否をできないということになっておりますが、その内容について教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"身体障害者補助犬法の改正ですが、４月から施行される内容につきましては、今、委員おっしゃっていただいたとおり、事業所・事務所に勤務する身体障害者のところにおいても犬の使用を受け入れるように義務付けられたこと。","voiceIndex":255,"id":"exchange-109"},{"speaker":"山路委員","kind":"質問・要望","question":"５６人以上の企業が、今回対象になるということですので、前回の平成６年はまだ品川区にはいらっしゃらないということでしたが、補助犬も訓練を受けて、だんだん広がっておりますので、こういうことが品川区で起きたときには、ぜひよろしくお願いします。品川区では対象の方はあるんでしょうか。あったらお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"今、私どもで障害者登録の中で実際上盲導犬、介助犬、聴導犬を使っているという方については、ちょっと私の方では把握しておりません。ですが、もし使う場合については、私どもと相談しながら利用できるように配慮していきたいと思いますので、よろしくお願いします。","voiceIndex":257,"id":"exchange-110"},{"speaker":"山路委員","kind":"質問","question":"相談窓口も、東京都は持っているそうですけど、連携して、品川区でもより拡大の方向でよろしくお願いいたします。次に行きます。ＩＳＯ認証取得に関しましては、９００１と１４００１は品川区で取得をされておりますが、今回初めてＩＳＯ２７００１／ＩＳＭＳ、もう１点はＩＳＯＴＳ１６９４９という新しい支援事業を開始される予定ですが、その内容についてどういう支援をされるかお伺いいたします。","respondent":"金子産業振興課長","answer":"企業からも要望があり、また最近増えているのが、ご紹介いただきました２７００１という情報セキュリティマネジメント認証基準というものと、それからＴＳ１６９４９というのは、実はこれはＩＳＯの９００１、品質マネジメントシステムをベースにして。","voiceIndex":259,"id":"exchange-111"},{"speaker":"山路委員","kind":"質問","question":"補助金はどれぐらいですか。前回は約半額ぐらいでしたっけ。それで何社ぐらい予定をされているか。そしてどういう効果をねらわれているかお伺いいたします。","respondent":"金子産業振興課長","answer":"私ども、こういったものを助成している趣旨は、中小企業が様々な大企業に納入する、あるいは販売するに際して、国際的基準を取得して、そういったものが有利になるようなことを支援していこうということで助成をしているものです。","voiceIndex":261,"id":"exchange-112"},{"speaker":"山路委員","kind":"質問・要望","question":"ＣＯ２削減と、また商品の国際的ＰＲと両方の面で大事だと思いますので、どうぞよろしくお願いします。続いて消費生活の安全・安心の確保、２,５５８万７,０００円計上してありますが、拡大するということで、相談員の方が１人増えるのかなと思いますけど、中身についてちょっとお知らせいただきたいと思います。","respondent":"鷹倉区民課長","answer":"平日ですと、非常勤という関係もございまして、２ないし３名という形で対応しておったわけですが、常時３名で対応していきたいということと、それから第４火曜日ですが、夜の７時ごろまで、電話の部分ですが延長して。","voiceIndex":263,"id":"exchange-113"},{"speaker":"山路委員","kind":"質問","question":"悪質商法を妨げることといたしまして、福岡市では近所の方をボランティアで募集をして、近所ごと、そのご自宅につきまして、高齢者のお１人の方に徹底していくというんですね。クーリングオフ等のやり方などを。そういうものを検討してはどうかと思いますが、どのようにお考えでしょうか。","respondent":"鷹倉区民課長","answer":"強めていく中の一つの重要なものが、地域の情報を我々がすばやくつかんで、すばやく対応していくというものを柱にすえていきたいと考えているところです。","voiceIndex":265,"id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"３点ほどお聞きしたいと思います。２３１ページ、乳がん検診。２３７ページの健康センター事業費。それから２４３ページのエコクリーン事業所認定と、関連して地球にやさしいお店発見についてお聞きします。乳がん検診ですが、障害のある方、いろいろな方がいらっしゃると思うんですが、その方はどういう方法をとられているのか。それから利用方法についてお聞きします。","respondent":"太田健康課長、田村環境課長","answer":"それとファクシミリ等の申し込みも受けてありますので、そういう意味から言うと、個別の方の各状態については把握をしておりませんので、聴覚障害の方はファクシミリで可能かと思いますけれども、肢体不自由とかそういう方については。実際には何をやっているかといいますと、８項目、簡易包装の推進だとか、レジ袋の削減、環境配慮商品の販売促進、使い捨て容器・製品の販売および自粛、あるいは資源物の回収、あるいは自店で販売した商品の修理。","voiceIndex":268,"id":"exchange-115"},{"speaker":"西本委員","kind":"質問・要望","question":"乳がん検診ですから、マンモグラフィーにしても、触られたりするわけですよね。ですから、それは今後の課題になると思うんですけれども、それをよく考えていただきたいと思います。やはり拒否されてしまうんですよ。それをどういうふうにリンクさせていくのかというのは、来年度、いろいろ研究していただいて、実のあるものにしていただきたいと思いますので、ご意見をいただきたいと思います。","respondent":"太田健康課長、田村環境課長","answer":"１点目の乳がん検診についてですけれども、一定の設備を使って検診をするということからして、障害を持たれている方についてはなかなか難しい部分があろうかと思いますが、今後両医師会、それから関連の障害者福祉課等含めて。委員ご指摘のとおり、地球にやさしいお店、魅力ある内容で、さらに、画面展開も魅力あるもので、ぜひ区民の方に積極的に見ていただいて。","voiceIndex":271,"id":"exchange-116"},{"speaker":"西本委員","kind":"質問・要望","question":"１点、健康センターのところで、確認をしてください。ジャグジーのところの温度管理ができてないというふうにおっしゃっていますので。それから、子どもさんたちの使用方法ですね。それも何かしら注意を促す等、皆さんが気持ちよく使えるような仕組みをぜひつくっていただきたいと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２５７ページからの商店街振興、大型店出店についてお聞かせいただきたいと思います。２月半ばに突然、東急が中延駅の前に４階建ての店舗の計画を出してきました。初めに、区内に大型店、中規模店がどれぐらいあるか教えていただきたいと思います。それから、９１年と比べてどれぐらい増えているかということについてもお聞かせいただきたいと思います。","respondent":"金子産業振興課長","answer":"大型店の店舗の面積等々のお尋ねなんですけれども、東京都でとっている統計が５００m2と１,０００m2を一緒にしているところがありますので、ちょっと不十分な回答になるかもしれませんが、今現在、１,０００m2以上の大型店は、区内には２５店舗あります。","voiceIndex":276,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"売場面積の総売場面積に占める割合について教えていただきたいのと、それから２００４年の時点で５００m2以上が３２店舗ということですと、去年、おととしにライフとオオゼキが新たにできていると思うんですけど、それも加えると３４店舗ということで考えてよろしいでしょうか。","respondent":"金子産業振興課長","answer":"２００４年以降の大型店舗ですけれども、委員ご指摘のとおりのオオゼキとライフのほかに、２００４年以降ですと、全体で約５店舗ぐらいさらに新設されたものがありますので、もう少し数は行くと思います。","voiceIndex":278,"id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"９１年のときの２７から、５店舗プラスすると３７ということで、１０店舗も増えているのかなということだと、本当に５００m2以上の店舗がどんどん増えているというような感じがするんですけれども、旗の台のオオゼキとかは５００m2行かないので、こういうところも含めるともっと増えているのかなと思うんですけれども、この中規模店、それから大型店というのがどんどん増加していくというのが。","respondent":"金子産業振興課長","answer":"昨年もイトーヨーカドーの中で、そういったセールを５回実施しておりまして、かなり大きな成果を上げているところです。こういったものに対しましても、区としまして助成をしています。","voiceIndex":280,"id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"説明会が、今回の東急でも、突然２月１５日に看板が出されて、説明会が２１日に行われたんですが、商店街の方はだれも知らないんですね。この店舗が出ることによって、各地域、それから各商店街にどんな影響を及ぼすことになっていくのかという影響調査を東急自身がやっていくような指導というのが必要じゃないかと思うんですけど、この点についてはいかがでしょうか。","respondent":"金子産業振興課長","answer":"もう１点、影響調査についてですけれども、これにつきましては、私ども、商店街のお考えもお聞きして、今後この商店街の中でどういった取組みが様々できるかということについて協議をしながら、対応をしていきたいと考えております。","voiceIndex":282,"id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"商店街の方は、このことを本当に知らなかったんですね。それから、「事前調査を行い、適切な対応策を講じるように努めなければならない」と品川区の要綱にありますけれども、これは具体的にどういう形で、どう指導されていくんでしょうか。","respondent":"金子産業振興課長","answer":"例えば、必要な駐車台数、あるいは駐輪台数、それからごみの処理の問題、納品等に際しての騒音の問題、時間外に及んだ場合の影響等々、あるいは冷却、送風機等々非常に大きな音を出すものについての設置の位置と時間といったものについて届出をするように指導しています。","voiceIndex":284,"id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"私は２２７ページ、小児夜間診療事業と、２１６ページ、中小企業対策費についてお聞きします。そして、昭和大の４階に小児用の外来診療室を設けることになっていると。それからまた、他区の方かもしれませんが、小さなお子さんがいて「じゃあ、私もそちらに行く」という場面にも遭遇すると思うんですが、これは品川区の子どもだけの診療室なのかどうか、その辺詳しくお答えください。","respondent":"太田健康課長","answer":"そこに「品川区の小児夜間診療は４階です」という表示を１回の入口のところにしていただく予定になっております。そこで、入っていってエレベーターで４階に上がっていただくという中身になってありますので、あくまでも品川区の区民ということが対象です。","voiceIndex":287,"id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"例えば知らないでということもありますよね。じゃあ、その方たちは、確かに４階に行くわけですが、そのときに、例えば小さなお子さんが、隣接の大田区、目黒区もそうなんですが、そういうときはきちっとお断りするということなんでしょうか。それはちょっとお答えください。でも、昭和大学の場合には、間違いなく専門の小児科医がしっかり診察していただけるんでしょうか。その二つについてお答えください。","respondent":"太田健康課長","answer":"先ほどもご答弁しましたけれども、救急救命等の入口のところに「品川区の夜間診療」という表示をいたしますので、一般的に考えれば、４階の方へは区民以外はのぼらないかと思います。","voiceIndex":289,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"品川区でも専門の小児科医、産婦人科医が少ないというお話を昨年もしましたが、その後、品川区へ誘致するために、何か対応というのはとっているんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"大変残念ですけれども、開業も含めまして、医師を誘致するというのは大変難しい問題が多くて、先ほど東京都の施策に協力しているという話はしましたが、区独自でというところでは難しいです。","voiceIndex":291,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問・要望","question":"希望ですが、妊産婦健診もこれからきっと増えると思います。小児科というのも、品川区はお子さんが増えていますので、その辺のところはぜひ努力していただきたいと思います。品川区としては、２３区の中でも立派だと思うんですが、抜本的な対策として、現状のままでは、一生懸命やっている割には効果が出ていないんじゃないかなと思うんですが、その辺についてご見解をお聞かせください。","respondent":"金子産業振興課長","answer":"区としましては、様々な施策を講じて、委員のご指摘もありましたとおり、支援策を考えて実施してきているわけですけれども、商業につきましては、既にご案内かと思いますが、従来の商店街の支援から、リピーター等顧客を開拓するためには、一つ一つの商品。","voiceIndex":293,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望だけになっちゃうかもしれませんが、国では景気対策をするときに、公共事業や土木事業を実施して、民間の企業を使ってそこにお金を出していくという形をとっております。商店街にとっても、買い物に来てくれない。これは消費性向の問題もあります。今の景気の実態もあります。所得が減っているという実態もありますが、その辺何か新しい対応策を、区の方でもさらに努力して考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-127"},{"speaker":"堺委員","kind":"意見","question":"私の方から、２３１ページのがん対策、それから肝炎ウイルス検診、それから２５９ページの商店街に関連して３点お尋ねをしたいと思います。がんの件ですが、何人かの方からお話が出ておりましてだぶるかとは思いますが、がん対策基本法が制定されて、昨年６月にそれを受ける形でがん対策推進基本計画というのが国で定められました。その辺も含めまして、現況をお知らせいただけますか。","respondent":"太田健康課長","answer":"それから今後の計画ですけれども、１年１年、国の示された基本方針にのっとって努力していきたいです。","voiceIndex":297,"id":"exchange-128"},{"speaker":"堺委員","kind":"提案","question":"意識の啓発、区民への周知、粘り強くやっていくしかないかなと思いますので、この辺についてもぜひ取組みをお願いしておきたいと思います。それから２点目ですが、今回新規事業で喉頭がん検診、４０歳以上で５００件とありますけれども、私は平成３年１２月５日、今から１７年前になりますけれども、決算特別委員会のときに、喉頭がんの受診について提案をさせていただきました。","respondent":"太田健康課長","answer":"実施時期につきましては、新年度に入りましてなるべく早い時期にと考えていますが、委託については、医師会の方へ委託してまいります。契約医療機関で実施していきますので、両医師会とも、実施時期を含めて今後早急に、十分検討していきたいと思っているところです。","voiceIndex":299,"id":"exchange-129"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、いいことは早くお願いしたいなと思いますので、この件につきましては、ぜひそういう方向で取り組んでいただけるように要望しておきますので、ひとつご検討のほど、よろしくお願いいたします。これは、平成１９年度の当初予算で行きますと、肝炎検査委託、８７１万８,０００円、これは平成１９年度の当初予算です。それからこれの周知方法等について、あわせて確認の意味で教えていただけますか。","respondent":"太田健康課長","answer":"周知方法については、ホームページ等、それから広報等を通じまして実施していきたいと考えております。","voiceIndex":301,"id":"exchange-130"},{"speaker":"堺委員","kind":"提案","question":"それから最後に、２５９ページの商店街に関連して、今回、私は代表質問で、商店街にもＡＥＤの設置をしていただきたい、このことについて提案をさせていただきましたが、ご答弁の中でそういう方向で取り組んでいく旨のご答弁をたしかいただいたかと思うんですが、この辺につきましても、もう１回、できる限り早い時期に各商店街でこれを設置できるように取り組んでいっていただきたいと思いますが。","respondent":"金子産業振興課長","answer":"平成２０年度につきましては、現在武蔵小山商店街の方から２台の申請が出ておりまして、これについて当面助成していく考えです。","voiceIndex":303,"id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"２２９ページ結核予防費、２３１ページ健康診査、２３４ページ保健指導費、できましたら２３７ページ区民健康づくりについて質問します。それから、健康診査１,４００件という形で、４０歳以上の未加入の人、これは連絡等はどうやって、保険未加入ですから、どの人がどうだというのはわからないと思うけど、このあたりはどうするのか。その２点。","respondent":"倉橋品川区保健所保健サービス課長、太田健康課長","answer":"したがいまして、この数字というのは実績に基づいて計上しているものでございまして、ここのところ、ＱＦＴ検査、それからハイリスクに対する対策の重点化とか、いろいろ対策を打っているところですが。４月以降、特定健診は医療保険者に義務付けられておりますけれども、生活保護受給者については入っておりませんので、これは健康増進法による任意事業ということで区が実施をするということになっております。","voiceIndex":306,"id":"exchange-132"},{"speaker":"須藤委員","kind":"意見","question":"それから保健指導費。それから同じく乳児の健康診査、それから１歳６カ月、３歳児健診がそれぞれの人数に達しますと、乳児健診が８,０７０人、それから１歳児が２,７８０人、３歳児が２,５５０人という形で、医師の賃金等でやっていきますと、１人当たりの賃金が違ってくるんだけど、この辺はどうやってカウントしていくのか。その３点。","respondent":"川口品川区保健センター保健サービス課長","answer":"今年度、平成１９年度からは、ご案内のように、それに加えて児童センターとの連携のもとに、訪問を希望するしないにかかわらず、全戸訪問を第一として、現在実施をしています。","voiceIndex":309,"id":"exchange-133"},{"speaker":"須藤委員","kind":"質問","question":"健診は今、カウントした２,７８０で割ったので、それで五千幾ら、四千幾らと数字が違うので、どうですかと質問させてもらって、いろいろメンバーが違うから、そういうカウントをせざるを得ないんだろうと思います。最後に区民健康づくりのところで、先ほどもお話があったように、ここでは中高年という形でつくっているんだけれども、教育委員会と連携して、お子さんたちのをどういうふうにされているのかと。","respondent":"川口品川区保健センター保健サービス課長","answer":"さらに１歩進めて、先ほども午前中にお答えしましたように、今度は教育委員会との連携も、今現在、既に始めているところです。","voiceIndex":311,"id":"exchange-134"},{"speaker":"土井委員","kind":"質問","question":"私からは、２５１ページ清掃総務費に関連をして、それから同じく２５３ページの収集作業、運搬作業の車両購入についてお伺いをすること。続いて産業経済費の中では、商店街は皆さんいっぱいご質問がありましたので、製造業活性化支援事業に関連をする幾つかの事項についてご質問したいと思います。清掃関係、全部聞きます。","respondent":"田村環境課長、島袋品川区清掃事務所長","answer":"私の方から２４３ページの職員給与費についての内訳についてご説明します。３４人の中の環境清掃事業部が２９名、そのうちの環境課分が２４名、資源循環推進課が５名、あわせて２９名です。金額的には職員の給与、職員手当、共済等です。先ほどもご質問ございましたけれども、例の分別変更に伴う冊子をつくるですが、ここに従事する職員ですけれども、現在はデザイン等を考えて、資源循環推進課と。","voiceIndex":314,"id":"exchange-135"},{"speaker":"土井委員","kind":"質問・要望","question":"それは採用するんですかねとお伺いしたら、何となくちょっと危ない話のように聞こえたんですけれども、これはそれを採用する予定だということを意味しているんですか。そういうことですよね。その辺を含めて、ちょっと伺いたかったということです。それから、実態調査の方は完全に委託ですか。これもまた、集合住宅に入っていって「こんにちは」とやるのかなと思ったものですから、それはわかりました。","respondent":"金子産業振興課長","answer":"この域内の４自治体、かなり地域が広くなってしまいますけれども、域内の様々な企業、あるいは大学、学術機関、あるいは産業支援機関、こういったものとの連携を大きく発展させていこうということのもとに、本年、新製品・新技術コンクールを実施するものです。","voiceIndex":317,"id":"exchange-136"},{"speaker":"土井委員","kind":"質問・要望","question":"その意味で、ぜひよろしくお願いしたいと思います。それから、モデル地区実施とかいろいろとありますので、人の差配については環境の方も清掃の方もどうぞよろしく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問・要望","question":"サーマルリサイクルを中心に伺います。この間、地球温暖化を加速するサーマルリサイクル中止を求めてきましたけれども、ごみ問題は、廃棄物の処理をどうするのかといった出口の対策ではなく、廃棄物となるものをつくらない、入口の対策に重点を置く方向に、今、移っていると思います。資源の浪費、無駄をなくす。私はぜひ、ゼロ・ウェイストを目指して施策を進めてほしいと思っていますが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"資源回収の増であるとか、ごみの排出量の減という目標を掲げておりますので、それを着実に進めていくというのが基本的な姿勢です。","voiceIndex":321,"id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問","question":"とても物足りないお答えで、着実に進めていく、どのような方向を目指すのかという大きなところを伺ったので、もうちょっとお答えをしていただきたかったと思います。タイトルは「２３区発！ごみゼロへビジョン」。３Ｒを掲げている品川区としても、ぜひ全プラスチックを資源として回収し、プラスチックは燃やさない、この方針を打ち出すべきであると思いますが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"ですので、私どもとしては、容リ法の精神にのっとって、プラスチックの資源化を進めていくという方向で考えております。","voiceIndex":323,"id":"exchange-139"},{"speaker":"飯沼委員","kind":"確認","question":"港区では、全プラスチックの受け入れルートを既に確認しているという話を聞きましたけれども、港区が全プラスチックの資源回収に至る経緯を伺ったところ、プラスチックの８５％は容器包装リサイクルのプラスチックであって、その他は１５％であるということでした。ぜひ、この点を見習ってほしいと思いますが、いかがでしょうか。品川区でも、ぜひ食器の貸出しに取り組んでほしいんですが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"そういう中でプラスチックの減量、発生抑制ということに関しましては、マイバッグ運動ですとかいろいろ事業は進めておりますので、品川区としてももちろん、まずは発生抑制ということに変わりはないと考えています。","voiceIndex":325,"id":"exchange-140"},{"speaker":"飯沼委員","kind":"質問・要望","question":"食器の貸出しの件は、研究課題ということでは前向きに検討してていただけるというように受けとってよろしいんでしょうか。でそこを教えてください。私は大変なことであると思うんですが、この間ずっと、生ごみのリサイクルをしてほしい、私も追い求めてきたテーマなので、品川区でもぜひこの生ごみの資源化、前進をしていただきたい、すべきであると思っていますが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"発生抑制、具体的なですけれども、分別変更のＰＲ、それから今までのモデル地区への説明に入っている場合には、もちろん発生抑制ということを前段でお話した上で、分別の変更等をＰＲしているですので、各分別変更の説明会等では、まず発生抑制というのはもちろん強調しています。","voiceIndex":327,"id":"exchange-141"},{"speaker":"飯沼委員","kind":"質問・要望","question":"生ごみのところ、前進というお願いですので、ぜひ、今の状況よりもさらに進めていただきたいと思います。こういった仕組みが、今、できてしまっているという状況なんですが、私は品川区は、ぜひ区民の皆さんに正しい情報をきちんと説明をして、区民参加で意見を十分に聞いて、共同でこのごみの減量を進めていただくスタイルに、ぜひ変えていただきたいと思いますが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"手間のかからない、何でもかんでも燃やしていいというような説明をしたつもりはございませんし、実際、プラスチック製の容器包装の排出量はどんどん増えてきておりますので、区民の方々のご理解をいただけていると考えています。","voiceIndex":329,"id":"exchange-142"},{"speaker":"三上委員","kind":"質問・要望","question":"２２９ページの感染症予防費、それから２４３ページの区有施設自然エネルギー活用例ホームページ作成、２４６ページのリサイクル推進費という中でお伺いしたい。それから、商店街の方では、装飾灯小規模改修助成、それから装飾灯建替等施設整備助成について、簡単でいいですから、どういう仕組みで受けられるのかということについてお教えいただきたいと思います。","respondent":"倉橋品川区保健所保健サービス課長、田村環境課長、秋山資源循環推進課長、金子産業振興課長","answer":"ところが、予防接種の普及、それから麻しんの感染の減少によりまして、自然流行がなくなった状態では、２０年、３０年。私の方から区有施設の自然エネルギー活用例のホームページについてご説明します。そのＮＰＯ法人では、不要となった入れ歯をリサイクルして、世界の貧しい子どもたちの支援を進めて、金属を集めて売った収益金については。小規模改修事業の方は、これは緊急対応として考えておりますので、これにつきましては東京都の補助もありません。","voiceIndex":332,"id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"そういったときに、抵抗力がどの程度あるのかということについても、お医者さんは把握できるわけですから、そのときにしっかりとアドバイスをしていただけるような仕組みをやっていくことによって、また医療費もそんなに金額は大きくならないかもわかりませんし、注意深い健康管理ができていくんじゃないかと思いますので、そういった点での取組みをお願いしたいと思います。時間があればご答弁いただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":337,"id":"exchange-144"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"区内に掘り当てられている温泉が何カ所あるか、ご存じだったら教えていただきたいと思います。それから２３３ページ、アレルギー等居住環境調査指導事業、これも簡単で結構ですので、事業内容を教えていただきたいと思います。助成があるのは商店街のところしかないからここで聞いているんだけども、こういう商店街と同じような助成があるのかないのか、そこら辺を教えていただきたい。","respondent":"太田健康課長、金子産業振興課長、平澤品川区保健センター衛生課長","answer":"区内で掘り当てられている温泉は、公衆浴場では４カ所ですので、休業中を含めますと６カ所になろうかと思います。私ども、商店街にかかわるものについては商店街の助成対象になるように指導しておりますし、また、観光に関しましても、様々最近取り組んでおりますが。区内のアレルギー住宅に関係する事業でございまして、私どもの方で、例えばシックハウスに関することの相談等を受けつけている事業です。","voiceIndex":339,"id":"exchange-145"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"温泉の方からなんですけれども、４カ所はいいんだけど、２カ所ある。こういう情報はとるべきだろうと思う。調査をするのも構いません。こういうことを考えるのであれば、例えば町会だ、学校だ、みんなでやっているよというのが理解できたら、これはもう３分の２出そうとか、例えばにぎわいみたいに半分出そうとか、こういう制度をある程度つくってほしいなと思うんですけれども、それの答弁をお願いします。","respondent":"山岡品川区保健所衛生課長、田中区民生活事業部長、平澤品川区保健センター衛生課長","answer":"まもなく営業を開始するときに当たっては、我々のところに利用許可申請が出てくるものと思います。それの支援という話ですが、これから４次長計の中で、コミュニティーのあり方、それぞれの地域の中でいろいろ課題が違いますので。初めに、街頭活動といたしまして、西大井福祉まつり、ならびに荏原リビングフェア、さらに生活展等で、実際に区民の方に関するご説明活動をしています。","voiceIndex":343,"id":"exchange-146"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"商店街というか、長計の話が出たんですけれども、いいです。長計で私もまた委員になりそうなので、また言わせていただきますけれども、権限と責務というのは非常に大切で、協働ということもうたわれているわけですから、そこら辺のところはぜひよろしくお願いしたいなと思います。シックハウスは、そういうところでやってもあれだけれども、そこら辺はしっかり打ち出してほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":347,"id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":116047,"voices":348}}]);
